local config = {
  str_homestory_N26dianying_90060101_1_dialog_content = "เราอยู่ที่นี่ สิ่งที่คุณกำลังมองหาควรจะอยู่ในห้องเรียนนี้ ใช่?",
  str_homestory_N26dianying_90060101_2_dialog_content = "Ahhh ช่างเป็นความช่วยเหลือที่ดี",
  str_homestory_N26dianying_90060101_3_dialog_content = "ไม่บ่อยนักที่คุณจะได้เห็นเด็กที่กระตือรือร้นเช่นนี้ในทุกวันนี้",
  str_homestory_N26dianying_90060101_4_dialog_content = "คำเยินยอคืออะไร? อย่าเข้าใจผิด ไม่ใช่ว่าฉันอยากอยู่ที่นี่ เพราะฉันได้ยินคุณพูดว่าทุกคนอาจตกอยู่ในอันตราย...",
  str_homestory_N26dianying_90060101_5_dialog_content = "ทุกคน? ฟังดูยิ่งใหญ่ เพื่อนสาวขี้โอ่ของฉัน แต่ฉันมีความเข้าใจที่ไม่แม่นยำเสียทีเดียว",
  str_homestory_N26dianying_90060101_6_dialog_content = "ฉันสงสัยว่าคุณเป็นห่วงผู้หญิงคนนั้นเป็นส่วนใหญ่",
  str_homestory_N26dianying_90060101_7_dialog_content = "...",
  str_homestory_N26dianying_90060101_8_dialog_content = "ประธานสภานักเรียน หืม?",
  str_homestory_N26dianying_90060101_9_dialog_content = "H-คุณรู้ได้อย่างไร?!",
  str_homestory_N26dianying_90060101_10_dialog_content = "อย่าประเมินข่าวกรองของฝ่ายความมั่นคงต่ำไป",
  str_homestory_N26dianying_90060101_11_dialog_content = "ถ้าฉันพูดถูก มีจดหมายรักที่ยังไม่ได้ส่งอยู่ในกระเป๋าของคุณ",
  str_homestory_N26dianying_90060101_12_dialog_content = "!!!",
  str_homestory_N26dianying_90060101_13_dialog_content = "ตอนนี้อย่าเพิ่งประมาทเรา",
  str_homestory_N26dianying_90060101_14_dialog_content = "เอาล่ะ พ่อหนุ่ม ทำตัวให้เป็นธรรมชาติ มิฉะนั้น คุณจะปล่อยแมวออกจากกระเป๋า",
  str_homestory_N26dianying_90060101_15_dialog_content = "ยังไงก็ไม่มีใครเชื่อ แม้แต่ประธานสภานักเรียนคนนั้นที่คุณชอบมาก",
  str_homestory_N26dianying_90060101_16_dialog_content = "ดีแล้ว เดาว่ามันดีที่สุดที่จะไปกับคุณ",
  str_homestory_N26dianying_90060101_17_dialog_content = "จำไว้ว่าคุณบอกว่าคุณจะปกป้องเธอ",
  str_homestory_N26dianying_90060101_18_dialog_content = "แน่นอน. และเรามักจะรักษาสัญญาของเรา",
  str_homestory_N26dianying_90060101_19_dialog_content = "ตราบใดที่เธอไม่ใช่คนที่เราตามหา นั่นคือ",
  str_homestory_N26dianying_90060101_20_dialog_content = "ไปกันเถอะ",
  str_homestory_N26dianying_90060101_21_dialog_content = "เฮ้ มาทำอะไรที่นี่ คาเซม?",
  str_homestory_N26dianying_90060101_22_dialog_content = "S-ประธานสภานักเรียน...?",
  str_homestory_N26dianying_90060101_23_dialog_content = "<size=30>โอ้? ฉันไม่ได้คาดหวังว่าเธอจะมาที่นี่ ก็น่าสงสัย...</size>",
  str_homestory_N26dianying_90060101_24_dialog_content = "<size=45>ประธาน! คุณมาที่นี่ได้อย่างไร</size>",
  str_homestory_N26dianying_90060101_25_dialog_content = "ไม่ควรแปลกใจ! ฉันกำลังตรวจสอบอุปกรณ์สำหรับงานเทศกาลของมหาวิทยาลัย",
  str_homestory_N26dianying_90060101_26_dialog_content = "รองประธานและนักเรียนที่เป็นประโยชน์ที่นั่นช่วยตรวจสอบด้วย",
  str_homestory_N26dianying_90060101_27_dialog_content = "<size=30>ฉันคิดว่ามีความเป็นไปได้สูงที่จะมีวัตถุอันตรายซ่อนอยู่ในอุปกรณ์</size>",
  str_homestory_N26dianying_90060101_28_dialog_content = "<size=30>แล้วคุณล่ะกำลังคิดอะไรอยู่?</size>",
  str_homestory_N26dianying_90060101_29_dialog_content = "อืม... ฉันไม่รู้จักเพื่อนของคุณที่นี่ เธอมาจากโรงเรียนของเราหรือเปล่า",
  str_homestory_N26dianying_90060101_30_dialog_content = "เพื่อนของคุณที่นี่... ดูเหมือนจะไม่ได้เป็นส่วนหนึ่งของโรงเรียนของเรา",
  str_homestory_N26dianying_90060101_31_dialog_content = "รองประธาน...",
  str_homestory_N26dianying_90060101_32_dialog_content = "<size=30>เอ่อ... เธอเป็นรองประธานที่ระมัดระวังตัวเกินไปหรือเปล่านะ?</size>",
  str_homestory_N26dianying_90060101_33_dialog_content = "<size=30>นี่อาจไม่ง่ายขนาดนั้นแม้ว่าจะดูจริงใจก็ตาม</size>",
  str_homestory_N26dianying_90060101_34_dialog_content = "<size=30>ช่วยคิดหน่อยเร็ว</size>",
  str_homestory_N26dianying_90060101_35_dialog_content = "ได้สิ จะลองดูนะ",
  str_homestory_N26dianying_90060101_36_dialog_content = "เธอ...เธอ...",
  str_homestory_N26dianying_90060101_37_option_content = "แฟน",
  str_homestory_N26dianying_90060101_38_dialog_content = "เป็นแฟนของคุณ! ปลูกคู่แล้วพูดเลย!",
  str_homestory_N26dianying_90060101_39_dialog_content = "S-เธอเป็นแฟนฉัน!",
  str_homestory_N26dianying_90060101_40_dialog_content = "เอ่อ คุณไม่คิดว่านั่นเป็นทางเลือกที่ค่อนข้างอันตรายนะชับบ์",
  str_homestory_N26dianying_90060101_41_dialog_content = "แฟนจี?!",
  str_homestory_N26dianying_90060101_42_dialog_content = "ตั้งแต่เมื่อไหร่?!",
  str_homestory_N26dianying_90060101_43_dialog_content = "<size=30>ไม่คิดว่านายจะสนใจฉัน ชายหนุ่ม...</size>",
  str_homestory_N26dianying_90060101_44_dialog_content = "<size=30>ฉันไม่ได้คาดหวังว่าคุณจะสนใจฉัน ชายหนุ่ม! แต่ฉันขอโทษ หัวใจของฉันเป็นของคนอื่นไปแล้ว</size>",
  str_homestory_N26dianying_90060101_45_dialog_content = "<size=30>คุณไม่คิดว่าคำแก้ตัวแบบนี้ชัดเจนเกินไปเหรอ?</size>",
  str_homestory_N26dianying_90060101_46_dialog_content = "<size=30>และข้ออ้างแบบนี้ไม่เป็นผลดีกับสถานการณ์</size>",
  str_homestory_N26dianying_90060101_47_dialog_content = "ฉ-ฉันขอโทษ...",
  str_homestory_N26dianying_90060101_48_option_content = "ลูกพี่ลูกน้อง",
  str_homestory_N26dianying_90060101_49_dialog_content = "แค่บอกว่าเธอเป็นญาติของคุณ! ก้าวขึ้น!",
  str_homestory_N26dianying_90060101_50_dialog_content = "โอ้ นี่คือลูกพี่ลูกน้องของฉัน ใช่!",
  str_homestory_N26dianying_90060101_51_dialog_content = "พวกมันดูไม่มีอะไรเหมือนกันเลย แทบจะไม่เกี่ยวข้องกันเลย ชับบ์",
  str_homestory_N26dianying_90060101_52_dialog_content = "โอ้ลูกพี่ลูกน้องของคุณ! คุณจะไม่แนะนำเรา?",
  str_homestory_N26dianying_90060101_53_dialog_content = "โอ้ ลูกพี่ลูกน้องของคุณ เธอเหรอ? คุณจะไม่แนะนำเรา?",
  str_homestory_N26dianying_90060101_54_dialog_content = "มันเป็นแค่ฉันหรือความคลาดเคลื่อนของอายุเล็กน้อย?",
  str_homestory_N26dianying_90060101_55_dialog_content = "ฉันอดไม่ได้ที่จะรู้สึกว่ามีบางอย่างผิดปกติเล็กน้อยเกี่ยวกับช่องว่างระหว่างวัย",
  str_homestory_N26dianying_90060101_56_dialog_content = "ไม่ไม่. เธอดูเป็นผู้ใหญ่เสมอสำหรับอายุของเธอ เธอดูเป็นแบบนี้ตั้งแต่เธออายุแปดขวบ",
  str_homestory_N26dianying_90060101_57_dialog_content = "อย่างนั้นเหรอ? นั่นเป็นสิ่งที่จริง ...",
  str_homestory_N26dianying_90060101_58_dialog_content = "<size=30>คุณกำลังสนทนาขยะ</size>",
  str_homestory_N26dianying_90060101_59_dialog_content = "<size=30>แค่นี้ก็รู้สึกผิด...เริ่มสงสัยบท...</size>",
  str_homestory_N26dianying_90060101_60_dialog_content = "<size=30>แค่นี้จะทำให้ทุกคนสนใจฉันมากขึ้นไม่ใช่เหรอ?</size>",
  str_homestory_N26dianying_90060101_61_dialog_content = "<size=30>ลืมมันไปเถอะ นี่จะทำให้ทุกคนสนใจฉันมากยิ่งขึ้น</size>",
  str_homestory_N26dianying_90060101_62_dialog_content = "โทษที...",
  str_homestory_N26dianying_90060101_63_option_content = "เพื่อนบ้าน",
  str_homestory_N26dianying_90060101_64_dialog_content = "ดีที่สุดแค่บอกว่าเธอเป็นเพื่อนบ้าน มันต้องปลอดภัย!",
  str_homestory_N26dianying_90060101_65_dialog_content = "S-เธอคือเพื่อนบ้านข้างบ้านของฉัน",
  str_homestory_N26dianying_90060101_66_dialog_content = "อดไม่ได้ที่จะรู้สึกเหมือนกำลังขุดหลุมศพตัวเอง เจ้าปลาน้ำจืด",
  str_homestory_N26dianying_90060101_67_dialog_content = "เพื่อนบ้าน?",
  str_homestory_N26dianying_90060101_68_dialog_content = "ประธานสภานักเรียนไม่ได้อยู่ข้างๆ คุณเหรอ?",
  str_homestory_N26dianying_90060101_69_dialog_content = "ประธานเทเรซ่า คุณจำเธอได้ไหม?",
  str_homestory_N26dianying_90060101_70_dialog_content = "ไม่... ไม่ ฉันไม่...",
  str_homestory_N26dianying_90060101_71_dialog_content = "คุณเพิ่งย้ายเข้ามาในพื้นที่หรือไม่?",
  str_homestory_N26dianying_90060101_72_dialog_content = "โอ้ ฮ่าฮ่าฮ่า... ฉัน ฉันทำผิดไปแล้ว",
  str_homestory_N26dianying_90060101_73_dialog_content = "<size=30>คุณเป็นคนที่หลงทางจริงๆ คิดอะไรไม่ออกแล้วดีกว่าไหม?</size>",
  str_homestory_N26dianying_90060101_74_dialog_content = "<size=30>ฉันขอโทษ! ขอคิดก่อนนะ...</size>",
  str_homestory_N26dianying_90060101_75_dialog_content = "... เข้าใจแล้ว! ฉันเพิ่งบังเอิญชนเธอระหว่างทางมาที่นี่ เธอเป็นหนึ่งในศิษย์เก่าของโรงเรียนเรา",
  str_homestory_N26dianying_90060101_76_dialog_content = "เธอเคยได้ยินเกี่ยวกับเทศกาลในมหาวิทยาลัยของเรา ซึ่งทำให้เธอนึกถึงช่วงเวลาที่เธออยู่ที่นี่ เธอจึงอยากมาด้วย",
  str_homestory_N26dianying_90060101_77_dialog_content = "เป็นไงล่ะนักเรียนเก่า เอ๊ะ?",
  str_homestory_N26dianying_90060101_78_dialog_content = "นั่นทำให้เธอดูแก่ขึ้น",
  str_homestory_N26dianying_90060101_79_dialog_content = "(ไปได้ดี เจ้าหนู ดูเหมือนว่าเราจะตำหนิมันไปแล้วในตอนนี้)",
  str_homestory_N26dianying_90060101_80_dialog_content = "ตรวจสอบอุปกรณ์ทั้งหมดเรียบร้อยแล้ว ท่านประธาน",
  str_homestory_N26dianying_90060101_81_dialog_content = "ขอบคุณครับ",
  str_homestory_N26dianying_90060101_82_dialog_content = "ด? เด็กผู้ชาย? เธอจะข้ามบทบาทหรือไม่?",
  str_homestory_N26dianying_90060101_83_dialog_content = "เบเธลกำลังด้นสด",
  str_homestory_N26dianying_90060101_84_dialog_content = "ถ้าอย่างนั้น โปรดอย่าลังเลที่จะมองไปรอบๆ และแจ้งให้เราทราบหากคุณมีข้อเสนอแนะใดๆ",
  str_homestory_N26dianying_90060101_85_dialog_content = "ยอดเยี่ยม! ฉันจะมองไปรอบ ๆ และเสนอแนวคิดใด ๆ จากมุมมองของบัณฑิตของฉัน",
  str_homestory_N26dianying_90060101_86_dialog_content = "นั่นอะไรคะ คุณประธาน?!",
  str_homestory_N26dianying_90060101_87_dialog_content = "นี่คือ... หม้อทอดใหม่ธรรมดาๆ?",
  str_homestory_N26dianying_90060101_88_dialog_content = "ฮะ? นั่นคือเครื่องทอดอาหารโดยไม่ต้องใช้น้ำมันใช่ไหม?",
  str_homestory_N26dianying_90060101_89_dialog_content = "ถูกตัอง. พวกเขาทั้งมีสุขภาพดีและเป็นที่นิยมอย่างบ้าคลั่งในขณะนี้",
  str_homestory_N26dianying_90060101_90_dialog_content = "<size=30>เข้าใจแล้ว... ดูเหมือนจะง่ายที่จะซ่อนบางอย่างในตะกร้าทอดเหล่านั้น</size>",
  str_homestory_N26dianying_90060101_91_dialog_content = "<size=30>อุปกรณ์ที่น่าสนใจอาจถูกกระตุ้นโดยสมมุติฐานจากความร้อน</size>",
  str_homestory_N26dianying_90060101_92_dialog_content = "<size=30>อุปกรณ์ที่น่าสนใจอาจถูกกระตุ้นโดยสมมุติฐานจากความร้อน ดีที่สุดที่จะมองเข้าไปข้างใน</size>",
  str_homestory_N26dianying_90060101_93_dialog_content = "ดูไม่ดีสำหรับการทำอาหารพูดตามตรง",
  str_homestory_N26dianying_90060101_94_dialog_content = "โอ้ นี่เป็นเพียงพร็อพที่ชมรมคอสเพลย์ของเราจัดเตรียมไว้ให้",
  str_homestory_N26dianying_90060101_95_dialog_content = "ไม่ใช่ว่า... โรงงานเล่นแร่แปรธาตุสร้างสิ่งนี้ขึ้นมาหรอกเหรอ?",
  str_homestory_N26dianying_90060101_96_dialog_content = "โรงงานเล่นแร่แปรธาตุของเทเรซ่า?",
  str_homestory_N26dianying_90060101_97_dialog_content = "ตลกมาก",
  str_homestory_N26dianying_90060101_98_dialog_content = "...",
  str_homestory_N26dianying_90060101_99_dialog_content = "(คุณบอกว่าจะตรวจภายใน? คิดว่าฉันทำได้?)",
  str_homestory_N26dianying_90060101_100_dialog_content = "นั่นคืออาหารจานพิเศษของฉัน!",
  str_homestory_N26dianying_90060101_101_dialog_content = "เพื่อนที่ดีมากให้สูตรแก่ฉัน มันคือบีทรูทบอร์ช",
  str_homestory_N26dianying_90060101_102_dialog_content = "มันสดชื่นและหล่อเลี้ยงจิตวิญญาณ",
  str_homestory_N26dianying_90060101_103_dialog_content = "บีท บอร์ชท์... คุณหมายถึง...",
  str_homestory_N26dianying_90060101_104_dialog_content = "โอ้ คุณต้องเคยกินบอร์ชต์ของเพื่อนฉันมาก่อน คาเซม",
  str_homestory_N26dianying_90060101_105_dialog_content = "ฉัน... ฉันก็ไม่รู้เหมือนกัน",
  str_homestory_N26dianying_90060101_106_dialog_content = "นี่ไม่ใช่บทสนทนาที่ดี ไม่ว่าคุณจะมองอย่างไร ดังนั้นมาเปลี่ยนหัวข้อกันเถอะ",
  str_homestory_N26dianying_90060101_107_dialog_content = "...",
  str_homestory_N26dianying_90060101_108_dialog_content = "(คุณต้องการตรวจสอบซุป...? จริงเหรอ อันที่จริงมันค่อนข้างอันตราย)",
  str_homestory_N26dianying_90060101_108X1_dialog_content = "อืม... ที่นี่ดูโล่งไปหน่อย",
  str_homestory_N26dianying_90060101_108X2_dialog_content = "บางทีพวกเขาอาจจะยังเตรียมของอยู่?",
  str_homestory_N26dianying_90060101_108X3_dialog_content = "เป็นไปได้ แต่ฉันได้กลิ่นของอันตรายอยู่ใกล้ๆ",
  str_homestory_N26dianying_90060101_109_dialog_content = "หา? ตะกี๊ว่าอะไรนะ?",
  str_homestory_N26dianying_90060101_110_dialog_content = "ไม่มีอะไร. คุณทำสิ่งที่คุณทำต่อไป ฉันจะดูรอบๆ สักหน่อย",
  str_homestory_N26dianying_90060101_111_dialog_content = "โอ๊ะ... ก็ได้ครับ",
  str_homestory_N26dianying_90060101_112_dialog_content = "ยังไงก็ตามคุณเกษม การเตรียมตัวอื่นๆ สำหรับเทศกาลที่กำลังจะมาถึงเป็นอย่างไรบ้าง?",
  str_homestory_N26dianying_90060101_113_dialog_content = "อืม สนามกีฬา...",
  str_homestory_N26dianying_90060101_114_dialog_content = "เฮ้! คุณชัดเจนเกินไป ทุกคนเห็นคุณแอบดูแบบนั้น!",
  str_homestory_N26dianying_90060101_115_dialog_content = "...",
  str_homestory_N26dianying_90060101_116_dialog_content = "(อะไรนะ? อยากให้ฉันหาทางซื้อเวลาให้พวกเรามากขึ้น? อะไรนะ เหมือนมีเครื่องตรวจจับอะไรซ่อนอยู่ในหน้ากากเพื่อดักจับสิ่งของอันตราย?)",
  str_homestory_N26dianying_90060101_117_dialog_content = "(อะไรนะ? อยากให้ฉันหาทางซื้อเวลาให้พวกเรามากขึ้น? อะไรนะ เหมือนมีเครื่องตรวจจับอะไรซ่อนอยู่ในกระเป๋าเพื่อมองหาสิ่งของอันตราย?)",
  str_homestory_N26dianying_90060101_118_dialog_content = "(คุณถ่ายทอดอะไรมากมายด้วยตาของคุณได้อย่างไร?)",
  str_homestory_N26dianying_90060101_119_dialog_content = "(ที่จริงทำไมฉันถึงรู้ว่าคุณหมายถึงอะไรอย่างชัดเจน!)",
  str_homestory_N26dianying_90060101_120_dialog_content = "Drat... ต้องปกปิดเธอบ้าง...",
  str_homestory_N26dianying_90060101_121_dialog_content = "มีอะไรเหรอเกษม? มีอะไรผิดปกติกับดวงตาของคุณหรือไม่?",
  str_homestory_N26dianying_90060101_122_dialog_content = "โอ ท่านประธานาธิบดี ฉัน...",
  str_homestory_N26dianying_90060101_123_option_content = "มาร้องเพลงกันเถอะ!",
  str_homestory_N26dianying_90060101_123_dialog_content = "ไม่มีเวลา! ใช้เสียงของคุณเพื่อดึงดูดความสนใจ!",
  str_homestory_N26dianying_90060101_124_dialog_content = "ฉันอยากจะร้องเพลงให้คุณฟังในเทศกาลมหาวิทยาลัย!",
  str_homestory_N26dianying_90060101_125_dialog_content = "หา?",
  str_homestory_N26dianying_90060101_126_dialog_content = "ฉันแอบฝึกเพลงนี้จากวิทยุ และฉันใช้ความพยายามอย่างมาก ดังนั้นจงฟัง!",
  str_homestory_N26dianying_90060101_127_dialog_content = "ฉันเป็นนักร้องที่ยอดเยี่ยมจริงๆ แค่คอยดูฉันร้องเสียงสูง!",
  str_homestory_N26dianying_90060101_128_dialog_content = "โอ้? คุณจะร้องเพลง? แล้วฉันจะประสานเสียง!",
  str_homestory_N26dianying_90060101_129_dialog_content = "โอ้? คุณจะร้องเพลง? Lemme มาพร้อมกับคุณด้วยเสียงระฆังเหล่านี้",
  str_homestory_N26dianying_90060101_130_dialog_content = "ทันใดนั้นก็ระเบิดเป็นเพลงเหมือนคนปัญญาอ่อน",
  str_homestory_N26dianying_90060101_131_dialog_content = "ช่างเป็นคนปัญญาอ่อน... ทันใดนั้นก็ระเบิดเป็นเพลง",
  str_homestory_N26dianying_90060101_132_dialog_content = "เรายังมีอะไรต้องเตรียมอีกมาก!",
  str_homestory_N26dianying_90060101_133_dialog_content = "เรายังมีอะไรให้เตรียมอีกมาก",
  str_homestory_N26dianying_90060101_134_option_content = "โปรดส่งคืนวิดีโอเทป!",
  str_homestory_N26dianying_90060101_134_dialog_content = "คุณจำวิดีโอได้ในทันที!",
  str_homestory_N26dianying_90060101_135_dialog_content = "ประธาน!",
  str_homestory_N26dianying_90060101_136_dialog_content = "หืมม?",
  str_homestory_N26dianying_90060101_137_dialog_content = "คืนวิดีโอที่ฉันให้คุณยืมได้ไหม!",
  str_homestory_N26dianying_90060101_138_dialog_content = "ฮะ? คุณให้ฉันยืมเมื่อวานนี้เท่านั้น!",
  str_homestory_N26dianying_90060101_139_dialog_content = "และคุณตกลงให้ฉันยืม \"Cloud Island Ultra Warrior: The General\" เป็นเวลาหนึ่งสัปดาห์...",
  str_homestory_N26dianying_90060101_140_dialog_content = "และตอนนี้คุณต้องการมันคืนทันที?",
  str_homestory_N26dianying_90060101_141_dialog_content = "อันที่จริง... ฉันลืมไปว่ามีวิดีโออื่นอยู่ในเคสนี้... บางอย่างที่ผู้หญิงไม่ควรดู!",
  str_homestory_N26dianying_90060101_142_dialog_content = "เนื้อหาของ \"Railway Warrior Bros\" นั้นนองเลือดเกินไป!",
  str_homestory_N26dianying_90060101_143_dialog_content = "โอ้ ข-เข้าใจแล้ว...",
  str_homestory_N26dianying_90060101_144_dialog_content = "ฟังนะ ฉันจะเอาอันขวามาทีหลัง",
  str_homestory_N26dianying_90060101_145_option_content = "วาฟเฟิล!",
  str_homestory_N26dianying_90060101_145_dialog_content = "นั่นไง! ภาพยนตร์เรื่องนี้เหมาะสำหรับคนทุกวัย ดูขนาด!",
  str_homestory_N26dianying_90060101_146_dialog_content = "ประธานเทเรซ่า!",
  str_homestory_N26dianying_90060101_147_dialog_content = "หืมม?",
  str_homestory_N26dianying_90060101_148_dialog_content = "คุณเป็นคนประเภทไหน...?",
  str_homestory_N26dianying_90060101_149_dialog_content = "ว-ทำไมจู่ๆถึงถามฉันแบบนั้นล่ะ??",
  str_homestory_N26dianying_90060101_150_dialog_content = "ฉัน-ถ้าคุณยืนยัน... คุณ...",
  str_homestory_N26dianying_90060101_151_dialog_content = "ไอโง่! ทำไมฉันต้องพูดเรื่องแบบนั้นต่อหน้าคนมากมายด้วย!",
  str_homestory_N26dianying_90060101_152_dialog_content = "อะแฮ่ม... ผิดปกตินิดหน่อย คาเซ็ม",
  str_homestory_N26dianying_90060101_153_dialog_content = "เอ่อ... ต้องขอโทษด้วยเหรอ?",
  str_homestory_N26dianying_90060101_154_dialog_content = "นี่คือสิ่งที่หนังสือเรียกว่า Line Drive หรือไม่?",
  str_homestory_N26dianying_90060101_155_dialog_content = "ฉันไม่ต้องการ!",
  str_homestory_N26dianying_90060101_155X1_dialog_content = "พูดอะไรของคุณเกษม!?",
  str_homestory_N26dianying_90060101_156_dialog_content = "ดีจริงๆ! ว่าไงรุ่นพี่ เป็นแค่ผมหรือว่าวันนี้พี่เกษมทำตัวแปลกๆ?",
  str_homestory_N26dianying_90060101_157_dialog_content = "ฮะ? อาวุโส? คุณกำลังมองหาอะไรที่นั่น?",
  str_homestory_N26dianying_90060101_158_dialog_content = "อุ๊ย ดูเหมือนฉันจะโดนกระทืบ",
  str_homestory_N26dianying_90060101_159_dialog_content = "ไม่มีอะไรให้ทำนอกจากเริ่มการสืบสวนของฉันใหม่... ด้วยปากกาเรืองแสงที่ลบความทรงจำ!",
  str_homestory_N26dianying_90060101_160_dialog_content = "ไม่มีอะไรให้นอกจากเริ่มต้นใหม่ด้วยประแจที่ลบความทรงจำนี้...!",
  str_homestory_N26dianying_90060101_161_dialog_content = "นี่ตู้ขายอัตโนมัติเหรอ คุณประธาน?",
  str_homestory_N26dianying_90060101_162_dialog_content = "เอ่อ นั่นสินะ",
  str_homestory_N26dianying_90060101_163_dialog_content = "ฉันคิดว่าผู้คนอาจต้องการดื่มคู่กับของว่าง",
  str_homestory_N26dianying_90060101_164_dialog_content = "เลยหาวิธียืมโดยเฉพาะ",
  str_homestory_N26dianying_90060101_165_dialog_content = "ว้าว มันค่อนข้างน่าประทับใจ ไม่น่าแปลกใจที่คุณเป็นประธานาธิบดี",
  str_homestory_N26dianying_90060101_166_dialog_content = "ฉันเป็นคนลากมันมาจนถึงที่นี่!",
  str_homestory_N26dianying_90060101_167_dialog_content = "...",
  str_homestory_N26dianying_90060101_168_dialog_content = "(สัญญาณตาอีกแล้ว... ห๊ะ? ตรวจพื้นที่แล้วเหรอ? ไม่มีสิ่งของอันตรายเหรอ?)",
  str_homestory_N26dianying_90060101_169_dialog_content = "(หยุดเดินต่อไป... ตู้ขายอัตโนมัตินั่นน่าสงสัยสุดๆ เต็มไปด้วยเครื่องดื่มมากมายที่ฉันไม่เคยเห็นมาก่อนด้วยซ้ำ!)",
  str_homestory_N26dianying_90060101_170_dialog_content = "(รสมิ้นท์ปลา? สนิมป๊อป? น้ำผัก?)",
  str_homestory_N26dianying_90060101_171_dialog_content = "(ตอนนี้เป็นเวลาที่จะสงสัยเกี่ยวกับเรื่องนี้จริง ๆ เหรอ! ฉันค่อนข้างจะสิ้นสุดการผูกมัดแล้ว!)",
  str_homestory_N26dianying_90060101_172_dialog_content = "(แล้วน้ำทำมาจากผักอะไรกันแน่ ไม่เหมือนชาแปลกๆ ใช่ไหม)",
  str_homestory_N26dianying_90060101_173_dialog_content = "แค่ต้องไปต่อ...",
  str_homestory_N26dianying_90060101_174_dialog_content = "นี่กลองชุดเหรอ มิสเพรสซิเดนท์?",
  str_homestory_N26dianying_90060101_175_dialog_content = "ใช่แน่นอน",
  str_homestory_N26dianying_90060101_176_dialog_content = "บางแผนกกำลังจะจัดคอนเสิร์ตในงานเทศกาล ดังนั้นพวกเขาจึงทิ้งไว้ที่นี่ก่อน",
  str_homestory_N26dianying_90060101_177_dialog_content = "เข้าใจแล้ว",
  str_homestory_N26dianying_90060101_178_dialog_content = "...",
  str_homestory_N26dianying_90060101_179_dialog_content = "(สิ่งที่เรากำลังมองหาอาจซ่อนอยู่ในถังซัก เราควรฉีกมันออกดีไหม)",
  str_homestory_N26dianying_90060101_180_dialog_content = "(เดี๋ยวก่อน ถ้าขาดก็ไร้ประโยชน์!)",
  str_homestory_N26dianying_90060101_182_dialog_content = "ไก่งวง คุณประธานาธิบดี?",
  str_homestory_N26dianying_90060101_183_dialog_content = "ทำไมเทศกาลต้องไก่งวง?",
  str_homestory_N26dianying_90060101_184_dialog_content = "อ๋อ นั่นมันแมวของนักเรียน... แต่ฉันไม่รู้ว่ามันไปเอาไก่งวงมาจากไหน...",
  str_homestory_N26dianying_90060101_185_dialog_content = "โอ้ใช่. คุณรู้ไหม ฉันเคยมีแมวที่ช่วยฉันทำงาน",
  str_homestory_N26dianying_90060101_186_dialog_content = "...",
  str_homestory_N26dianying_90060101_187_dialog_content = "(อะไรนะ? มีบางอย่างซ่อนอยู่ในไก่งวง? คุณต้องการตรวจสอบโดยไม่ทำลายมันเหรอ?)",
  str_homestory_N26dianying_90060101_188_dialog_content = "(จะ...เป็นไปได้เหรอ? ถ้าจัดการได้ ต้องสอนวิธีด้วย)",
  str_homestory_N26dianying_90060101_188X1_dialog_content = "มันว่างเปล่า...",
  str_homestory_N26dianying_90060101_188X2_dialog_content = "นี่เตรียมงานแคมปัสเฟสติวัลจริงๆหรอ?",
  str_homestory_N26dianying_90060101_188X3_dialog_content = "มันผิดปกติจริงๆ มีบางอย่างที่นี่มาก่อน",
  str_homestory_N26dianying_90060101_188X4_dialog_content = "นี่น่าสงสัยมาก ฉันต้องตรวจสอบอย่างระมัดระวัง!",
  str_homestory_N26dianying_90060101_188X5_dialog_content = "ป้องกันฉัน!",
  str_homestory_N26dianying_90060101_188X6_dialog_content = "ฮะ? แต่ไม่มีที่กำบังเลย!",
  str_homestory_N26dianying_90060101_190_option_content = "เต้นรำ!",
  str_homestory_N26dianying_90060101_190_dialog_content = "รีบใช้กระบวนท่าที่คุณฝึกฝนมานาน!",
  str_homestory_N26dianying_90060101_191_dialog_content = "ลืมไปเลย!",
  str_homestory_N26dianying_90060101_192_dialog_content = "ทุกคนโปรดดู—!",
  str_homestory_N26dianying_90060101_193_dialog_content = "การเต้นรำที่ยอดเยี่ยมและน่าทึ่งของฉัน!",
  str_homestory_N26dianying_90060101_193X1_dialog_content = "ท่านี้เป็นท่าเต้น Planet Walk ในตำนานหรือเปล่า? ชับบ์!",
  str_homestory_N26dianying_90060101_194_dialog_content = "อ๊าาา...!!",
  str_homestory_N26dianying_90060101_195_dialog_content = "เกษม วันนี้เธอจริงๆ...",
  str_homestory_N26dianying_90060101_196_dialog_content = "ตื่นเต้น!",
  str_homestory_N26dianying_90060101_197_dialog_content = "โอ้? ขอบคุณ!",
  str_homestory_N26dianying_90060101_198_dialog_content = "(เธอชอบฉันแบบนี้จริงเหรอ?)",
  str_homestory_N26dianying_90060101_199_dialog_content = "โง่แค่ไหน...",
  str_homestory_N26dianying_90060101_200_dialog_content = "คุณเสียสติไปแล้ว...",
  str_homestory_N26dianying_90060101_201_dialog_content = "วันนี้มีเรื่องแปลกๆ เกิดขึ้นกับคุณ",
  str_homestory_N26dianying_90060101_202_dialog_content = "สุดยอด! ช่วยสอนฉันเต้นหน่อยได้ไหม!",
  str_homestory_N26dianying_90060101_203_option_content = "ปาล์มอ่าน?",
  str_homestory_N26dianying_90060101_203_dialog_content = "รีบใช้ความรู้ที่เรียนมาจากหนังสือ...!",
  str_homestory_N26dianying_90060101_203X1_dialog_content = "ใช่! นึกถึงประเด็นที่กล่าวไว้ในหนังสือ \"เข้าใกล้ศัตรูอย่างรวดเร็ว\" เดี๋ยวนี้...",
  str_homestory_N26dianying_90060101_203X2_dialog_content = "เห็นได้ชัดจากชื่อหนังสือว่ามีปัญหามากมายกับมัน ชับบ์!",
  str_homestory_N26dianying_90060101_204_dialog_content = "ให้ฉันอ่านโชคชะตาของคุณบนฝ่ามือของคุณ!",
  str_homestory_N26dianying_90060101_205_dialog_content = "ฉันขอโทษ... ฉันรับเรื่องนั้นไม่ได้ แม้จะเป็นแค่บทสนทนาก็ตาม",
  str_homestory_N26dianying_90060101_206_dialog_content = "คุณเป็นคนงี่เง่า? ดีกว่าให้ฉันอ่านฝ่ามือของคุณ!",
  str_homestory_N26dianying_90060101_207_dialog_content = "ระหว่างที่เรากำลังดำเนินการ ให้ฉันแน่ใจว่าเส้นชีวิตของคุณสิ้นสุดลงในวันนี้",
  str_homestory_N26dianying_90060101_208_dialog_content = "แน่นอน และฉันจะยืนยันว่าเส้นชีวิตของคุณสิ้นสุดในวันนี้จริงๆ",
  str_homestory_N26dianying_90060101_209_dialog_content = "ดีจริงๆ! ว่าไงรุ่นพี่ เป็นแค่ผมหรือว่าวันนี้พี่เกษมทำตัวแปลกๆ?",
  str_homestory_N26dianying_90060101_210_dialog_content = "ฮะ? อาวุโส? คุณกำลังมองหาอะไรที่นั่น?",
  str_homestory_N26dianying_90060101_211_dialog_content = "อุ๊ย ดูเหมือนฉันจะโดนกระทืบ",
  str_homestory_N26dianying_90060101_212_dialog_content = "ไม่มีอะไรให้นอกจากเริ่มต้นใหม่ด้วยปากกาลบความทรงจำนี้...!",
  str_homestory_N26dianying_90060101_213_dialog_content = "ไม่มีอะไรให้นอกจากเริ่มต้นใหม่ด้วยประแจที่ลบความทรงจำนี้...!",
  str_homestory_N26dianying_90060101_214_option_content = "ยูเอฟโอ?",
  str_homestory_N26dianying_90060101_214_dialog_content = "วิธีดั้งเดิมมากมักจะได้ผลดีที่สุด!",
  str_homestory_N26dianying_90060101_215_dialog_content = "ตรงนั้น! ยูเอฟโอ!",
  str_homestory_N26dianying_90060101_216_dialog_content = "เร็ว ดูสิ!",
  str_homestory_N26dianying_90060101_217_dialog_content = "ยูเอฟโอ! ตรงนั้น!",
  str_homestory_N26dianying_90060101_218_dialog_content = "...",
  str_homestory_N26dianying_90060101_219_dialog_content = "...",
  str_homestory_N26dianying_90060101_220_dialog_content = "...",
  str_homestory_N26dianying_90060101_220X1_dialog_content = "...",
  str_homestory_N26dianying_90060101_221_dialog_content = "ดีจริงๆ ท่านจะดูเขาผู้อาวุโสหรือไม่? วันนี้เกษมทำตัวแปลกๆ",
  str_homestory_N26dianying_90060101_222_dialog_content = "ฮะ? อาวุโส? คุณกำลังมองหาอะไรที่นั่น?",
  str_homestory_N26dianying_90060101_223_dialog_content = "อุ๊ย ดูเหมือนฉันจะถูกกระทืบ",
  str_homestory_N26dianying_90060101_224_dialog_content = "ไม่มีอะไรให้นอกจากเริ่มต้นใหม่ด้วยปากกาลบความทรงจำนี้...!",
  str_homestory_N26dianying_90060101_225_dialog_content = "ไม่มีอะไรให้นอกจากเริ่มต้นใหม่ด้วยประแจที่ลบความทรงจำนี้...!",
  str_homestory_N26dianying_90060101_226_dialog_content = "...",
  str_homestory_N26dianying_90060101_227_dialog_content = "(ตรวจสอบตรงนี้เสร็จแล้วแต่ยังไม่ได้อะไร?)",
  str_homestory_N26dianying_90060101_228_dialog_content = "นี่อะไรคะ มิสเพรสซิเดนท์?",
  str_homestory_N26dianying_90060101_229_dialog_content = "โอ้! ฉันลืมที่จะพูด",
  str_homestory_N26dianying_90060101_230_dialog_content = "นี่คือไฮไลท์ของเทศกาล!",
  str_homestory_N26dianying_90060101_231_dialog_content = "เพียงแค่ดึงที่นี่และเครื่องจะวางไข่",
  str_homestory_N26dianying_90060101_232_dialog_content = "มีอาหารจานอร่อยที่แตกต่างกันมากมายในไข่แต่ละฟอง มันเป็นอุปกรณ์ที่วิเศษมาก!",
  str_homestory_N26dianying_90060101_233_dialog_content = "เราได้เครื่องเจ๋งๆแบบนี้มาเมื่อไหร่...?",
  str_homestory_N26dianying_90060101_234_dialog_content = "นักเรียนใจดีของเราบริจาคให้ เห็นได้ชัดว่ามันค่อนข้างแพง",
  str_homestory_N26dianying_90060101_235_dialog_content = "ของดีควรแบ่งปันกันทุกคน อิอิ",
  str_homestory_N26dianying_90060101_236_dialog_content = "ของโปรดของทุกคนอยู่ข้างใน ฮิฮิ",
  str_homestory_N26dianying_90060101_237_dialog_content = "บางทีเราควรถือโอกาสทดสอบมันอีกครั้ง และให้โอกาสคาเซ็มและรุ่นพี่ของเราเพื่อดูว่ามันเหลือเชื่อแค่ไหน",
  str_homestory_N26dianying_90060101_238_dialog_content = "<size=30>อุปกรณ์นี้น่าสงสัยและเป็นที่สุดท้ายที่สามารถซ่อนสิ่งที่อันตรายได้ เราควรคว้าโอกาสนี้ไว้</size>",
  str_homestory_N26dianying_90060101_239_dialog_content = "<size=30>เข้าใจแล้ว. ไม่ต้องกังวล.</size>",
  str_homestory_N26dianying_90060101_240_dialog_content = "แล้วได้โปรด...",
  str_homestory_N26dianying_90060101_243_dialog_content = "<size=30>เป็นไปได้อย่างไร...</size>",
  str_homestory_N26dianying_90060101_244_dialog_content = "<size=30>ดังนั้นสิ่งที่เราจะทำ?</size>",
  str_homestory_N26dianying_90060101_245_dialog_content = "<size=30>ออกจากที่นี่กันก่อน ฉันอาจจะโวยวายถ้าเราอยู่กันนานเกินไป</size>",
  str_homestory_N26dianying_90060101_246_dialog_content = "อา ฉันยังมีสิ่งที่ต้องทำ ฉันเกรงว่าฉันต้องไปแล้ว",
  str_homestory_N26dianying_90060101_247_dialog_content = "ฉันขอให้คุณทุกอย่างดีที่สุดสำหรับเทศกาลมหาวิทยาลัยของคุณ",
  str_homestory_N26dianying_90060101_248_dialog_content = "อ่าโอเค. ขอบคุณท่านผู้อาวุโส",
  str_homestory_N26dianying_90060101_249_dialog_content = "ออกไปอย่างนั้นเหรอ? มีบางอย่างที่ไม่ชอบมาพากลเกี่ยวกับผู้อาวุโสคนนี้",
  str_homestory_N26dianying_90060101_250_dialog_content = "...",
  str_homestory_N26dianying_90060101_251_option_content = "ประธานเป็นผู้ดำเนินการ",
  str_homestory_N26dianying_90060101_252_dialog_content = "ปล่อยให้นางเอกทำ!",
  str_homestory_N26dianying_90060101_253_dialog_content = "ประธานาธิบดีต้องการดำเนินการหรือไม่?",
  str_homestory_N26dianying_90060101_254_dialog_content = "อยากให้ท่านประธานทำจริงหรือ? คุณยังไม่ลืมสิ่งสำคัญเหรอชับบ์?",
  str_homestory_N26dianying_90060101_255_dialog_content = "ได้ ฉันจะหลอกตัวเอง",
  str_homestory_N26dianying_90060101_256_dialog_content = "ฮรือออออ—!",
  str_homestory_N26dianying_90060101_257_dialog_content = "ฮา! ไม่คิดว่าจะมีไข่",
  str_homestory_N26dianying_90060101_258_dialog_content = "ดูเหมือนไข่ธรรมดา...",
  str_homestory_N26dianying_90060101_259_dialog_content = "มีทีรามิสุอยู่ข้างใน",
  str_homestory_N26dianying_90060101_260_dialog_content = "หน่วยสืบราชการลับอาจผิดพลาดหรือไม่? ไม่มีอะไรให้นอกจากมองหาต่อไป",
  str_homestory_N26dianying_90060101_261_option_content = "ดำเนินการเอง",
  str_homestory_N26dianying_90060101_262_dialog_content = "ให้ฉันทำมัน อย่างน้อยคุณก็จะอุ่นใจ",
  str_homestory_N26dianying_90060101_263_dialog_content = "ได้!",
  str_homestory_N26dianying_90060101_264_dialog_content = "ดึงแค่นี้ใช่ไหม",
  str_homestory_N26dianying_90060101_265_dialog_content = "นั่นสิ",
  str_homestory_N26dianying_90060101_266_dialog_content = "เรียบร้อย!",
  str_homestory_N26dianying_90060101_267_dialog_content = "มันกระพริบและดูเหมือนจะมี Mille-feuille อยู่ข้างใน?",
  str_homestory_N26dianying_90060101_268_dialog_content = "<color=#e8d9bb>ปี๊บ—ปี๊บ—</color>",
  str_homestory_N26dianying_90060101_269_dialog_content = "รอ! นี่มันอะไรกัน!",
  str_homestory_N26dianying_90060101_270_dialog_content = "ดราก้อน ค้นพบแล้ว! แล้วฉันจะมีคุณทั้งหมด—!",
  str_homestory_N26dianying_90060101_271_dialog_content = "เกิดอะไรขึ้นน่ะ",
  str_homestory_N26dianying_90060101_272_dialog_content = "เกิดอะไรขึ้น? ฉันเฝ้ารอจุดสุดยอดมาทั้งคืน ชับบ์!",
  str_homestory_N26dianying_90060101_273_option_content = "เชิญผู้อาวุโส",
  str_homestory_N26dianying_90060101_274_dialog_content = "อืม เธอนำอุปกรณ์ตรวจจับวัตถุอันตรายมาด้วย ดังนั้นน่าจะปลอดภัยที่สุดหากให้ผู้อาวุโสตรวจสอบ",
  str_homestory_N26dianying_90060101_275_dialog_content = "ผู้อาวุโสอยากจะลองไหม?",
  str_homestory_N26dianying_90060101_275X1_dialog_content = "อืม คุณดูฉลาดขึ้นนิดหน่อยนะชับบ์!",
  str_homestory_N26dianying_90060101_276_dialog_content = "โอ้ ทางเลือกที่ชาญฉลาด แน่นอนฉันจะลองดู",
  str_homestory_N26dianying_90060101_277_dialog_content = "ไข่นี้มีของอร่อยอยู่ข้างใน?",
  str_homestory_N26dianying_90060101_278_dialog_content = "ฉันคิดว่ามันเป็นประตูป่าดำข้างใน",
  str_homestory_N26dianying_90060101_279_dialog_content = "(ฮะ? เครื่องตรวจจับของฉันมีปฏิกิริยา)",
  str_homestory_N26dianying_90060101_280_dialog_content = "ไม่มีใครขยับ! ฉันกับฝ่ายความมั่นคง!",
  str_homestory_N26dianying_90060101_281_dialog_content = "นี่คือตราของฉัน ตอนนี้ฉันจะพาทุกคนมาสอบสวน",
  str_homestory_N26dianying_90060101_282_dialog_content = "อาวุโส?",
  str_homestory_N26dianying_90060101_283_dialog_content = "ดราก้อน ค้นพบแล้ว! แล้วฉันจะมีคุณทั้งหมด—!",
  str_homestory_N26dianying_90060101_284_dialog_content = "เอ๊ะ? คุณกำลังทำอะไร นักเรียนกระตือรือร้นที่ไม่คุ้นเคย?",
  str_homestory_N26dianying_90060101_285_dialog_content = "ฮะ? อะไร เหตุใดคอนโทรลเลอร์จึงไม่ทำงาน",
  str_homestory_N26dianying_90060101_286_dialog_content = "ฮะ? อะไร เหตุใดคอนโทรลเลอร์จึงไม่ทำงาน แผนกอุปกรณ์ประกอบฉากดูแลไม่ดีเหรอ?",
  str_homestory_N26dianying_90060101_287_dialog_content = "ใจง่ายเกินไป เครื่องตรวจจับในหน้ากากของฉันมีเครื่องรบกวนสัญญาณขนาดเล็ก",
  str_homestory_N26dianying_90060101_288_dialog_content = "ใจง่ายเกินไป เครื่องตรวจจับของฉันมีเครื่องรบกวนสัญญาณขนาดเล็ก",
  str_homestory_N26dianying_90060101_289_dialog_content = "ให้ตายเถอะ... ทันทีที่เปิดใช้งาน ทั้งโรงเรียนจะกลายเป็นลูกกวาด เหมือนกับบ้านลูกกวาดในนิทาน!",
  str_homestory_N26dianying_90060101_290_dialog_content = "ฉันสามารถหลบหนีโดยซ่อนตัวอยู่ในกำแพงช็อคโกแลต ...",
  str_homestory_N26dianying_90060101_291_dialog_content = "ถ้าเป็นไปได้ ฉันอยากจะบินหนีไปด้วยเรือช็อคโกแลต",
  str_homestory_N26dianying_90060101_292_dialog_content = "... ถ้าอย่างนั้นระดับน้ำตาลในเลือดก็จะสูงเกินไป... ไม่สิ! มันอันตรายเกินไป!",
  str_homestory_N26dianying_90060101_293_dialog_content = "ฉันได้เฝ้าดูอาณาจักรคาร์โบไฮเดรตของคุณมาระยะหนึ่งแล้ว ดังนั้นคุณควรมาอย่างเงียบๆ",
  str_homestory_N26dianying_90060101_294_dialog_content = "ฉันได้เฝ้าดู Sugar Kingdom ของคุณมาระยะหนึ่งแล้ว ดังนั้นคุณทุกคนควรมาอย่างเงียบๆ",
  str_homestory_N26dianying_90060101_295_dialog_content = "คิดว่าจะพาฉันไปง่ายๆงั้นเหรอ?",
  str_homestory_N26dianying_90060101_296_dialog_content = "ฮะ? ฉันขยับไม่ได้!",
  str_homestory_N26dianying_90060101_297_dialog_content = "โอ๊ย...!",
  str_homestory_N26dianying_90060101_298_dialog_content = "ป-ประธาน...!",
  str_homestory_N26dianying_90060101_299_dialog_content = "คุณ...! นศ.ฮึด!",
  str_homestory_N26dianying_90060101_300_dialog_content = "ครั้งนี้คุณโชคดี ฉันเดาว่าฉันจะต้องใช้เอซให้สุดแขนเสื้อ",
  str_homestory_N26dianying_90060101_301_dialog_content = "แต่ความฝันอันสูงส่งของเราในการเสพติดน้ำตาลจะไม่ดับลง!",
  str_homestory_N26dianying_90060101_302_dialog_content = "เดี๋ยวเราก็จะได้รู้กัน!",
  str_homestory_N26dianying_90060101_303_dialog_content = "ไม่... ฉันจะไม่ปล่อยคุณไป...",
  str_homestory_N26dianying_90060101_304_dialog_content = "รองประธาน?!",
  str_homestory_N26dianying_90060101_305_dialog_content = "คิดว่าคุณสามารถทำให้เกิดความยุ่งยากในงานเทศกาลของมหาวิทยาลัยแล้วออกไปได้อย่างง่ายดาย?",
  str_homestory_N26dianying_90060101_306_dialog_content = "อะไร?! ทำไมคุณถึงย้ายได้?",
  str_homestory_N26dianying_90060101_307_dialog_content = "อะไร?! ทำไมคุณถึงย้ายได้? ผู้อำนวยการ! ไม่ถูกต้อง!",
  str_homestory_N26dianying_90060101_308_dialog_content = "ใครมายุ่งกับอุปกรณ์ของเรา? ฝ่ายรักษาความปลอดภัยของคุณคงไม่สามารถดึงสิ่งนี้ออกมาได้ แล้วใครกันล่ะ?!",
  str_homestory_N26dianying_90060101_309_dialog_content = "เอานี่ไปกินนี่ซะ!",
  str_homestory_N26dianying_90060101_310_dialog_content = "ส่งมอบของหวานทั้งหมด!",
  str_homestory_N26dianying_90060101_311_dialog_content = "ผู้ชายที่ต้องการให้ทุกคนติดน้ำตาลในงานเทศกาลถูกพรากไปแล้ว",
  str_homestory_N26dianying_90060101_312_dialog_content = "โอ้... แล้วฉันก็คิดว่าเขาเป็นนักเรียนที่กระตือรือร้นจริงๆ",
  str_homestory_N26dianying_90060101_313_dialog_content = "ฉันได้ขนมทั้งหมดคืนแล้วด้วย",
  str_homestory_N26dianying_90060101_314_dialog_content = "อย่างน้อยก็คืนความสงบสุขให้มหาวิทยาลัย",
  str_homestory_N26dianying_90060101_315_dialog_content = "แน่นอน! นี่คือวิทยาเขตของเรา",
  str_homestory_N26dianying_90060101_316_dialog_content = "ไม่ใช่แค่ผู้อาวุโสจากฝ่ายความมั่นคงเท่านั้น หลายคนกำลังมองหามันเช่นกัน",
  str_homestory_N26dianying_90060201_1_dialog_content = "โอ้ที่รัก ฉันสายไปแล้ว! ฉันแค่หวังว่าผู้ติดต่อยังไม่จากไป...",
  str_homestory_N26dianying_90060201_2_dialog_content = "ขอโทษครับ แต่นี่คือ Thorngate Inn หรือเปล่าครับ?",
  str_homestory_N26dianying_90060201_3_dialog_content = "แน่นอนมันเป็น",
  str_homestory_N26dianying_90060201_4_dialog_content = "เราให้บริการอาหารทุกประเภทที่นี่เหมาะสำหรับนักเดินทางที่เหนื่อยล้า",
  str_homestory_N26dianying_90060201_5_dialog_content = "ไม่ต้องพูดถึงเครื่องดื่มบางอย่างที่คุณจะไม่พบที่ใดในโลก",
  str_homestory_N26dianying_90060201_6_dialog_content = "ทำไมไม่ลองพักดูสินค้าของฉันดูล่ะ",
  str_homestory_N26dianying_90060201_7_dialog_content = "โรงแรมของฉันอาจดูไม่มาก แต่อาหารของเราชนะการประกวดทั่วราชอาณาจักร",
  str_homestory_N26dianying_90060201_8_dialog_content = "ดู? ที่นั่นคือถ้วยรางวัลที่ใหญ่ที่สุดของเรา",
  str_homestory_N26dianying_90060201_9_dialog_content = "แน่นอนว่าเป็นถ้วยรางวัลที่น่าสนใจ...",
  str_homestory_N26dianying_90060201_10_dialog_content = "เรายังมีกระสอบทรายจำนวนมากกระจายอยู่ทั่วโรงแรม",
  str_homestory_N26dianying_90060201_11_dialog_content = "ถ้าคุณต้องการคุณสามารถยืดขาของคุณในขณะที่",
  str_homestory_N26dianying_90060201_12_dialog_content = "นี่มันกำลังทำอะไรอยู่ในโรงเตี๊ยม...?",
  str_homestory_N26dianying_90060201_13_dialog_content = "โรงเตี๊ยมดูค่อนข้างสะอาด... ใช่ ฉันคิดว่าฉันจะอยู่อีกสักพัก",
  str_homestory_N26dianying_90060201_14_dialog_content = "มีที่นั่งว่างอยู่ตรงนั้น ทำตัวที่บ้านเพื่อน",
  str_homestory_N26dianying_90060201_15_dialog_content = "ที่นี่ทำได้ค่อนข้างดีสำหรับตัวเอง...",
  str_homestory_N26dianying_90060201_16_dialog_content = "ยังไม่ถึงเวลาอาหาร แต่โรงแรมก็เต็มไปด้วยลูกค้า!",
  str_homestory_N26dianying_90060201_17_dialog_content = "ไม่ว่าในกรณีใด ฉันมาที่นี่เพื่อพบเพื่อนเก่า ดังนั้นฉันจึงไม่ต้องการโต๊ะของตัวเอง",
  str_homestory_N26dianying_90060201_18_dialog_content = "สไตล์ดูไม่เข้าท่าที่นี่",
  str_homestory_N26dianying_90060201_19_dialog_content = "เจ้าของโรงแรมซื้อมันไว้ตอนไปเที่ยวต่างประเทศหรือเปล่า?",
  str_homestory_N26dianying_90060201_20_dialog_content = "ไม่ว่าในกรณีใด ฉันมาที่นี่เพื่อพบเพื่อนเก่า ดังนั้นฉันจึงไม่ต้องการโต๊ะของตัวเอง",
  str_homestory_N26dianying_90060201_21_dialog_content = "ตอนนี้มันไปไกลเกินไปแล้ว...",
  str_homestory_N26dianying_90060201_22_dialog_content = "ฉันไม่คิดว่าผ้าห่มจะจำเป็นจริงๆ แม้ว่าอากาศข้างนอกจะหนาวสักหน่อยก็ตาม!",
  str_homestory_N26dianying_90060201_23_dialog_content = "ไม่ว่าในกรณีใด ฉันมาที่นี่เพื่อพบเพื่อนเก่า ดังนั้นฉันจึงไม่ต้องการโต๊ะของตัวเอง",
  str_homestory_N26dianying_90060201_23X1_dialog_content = "เสียดายที่ร้านยังปรับปรุงอยู่...ไม่มีแม้แต่โต๊ะเก้าอี้",
  str_homestory_N26dianying_90060201_23X2_dialog_content = "เนื่องจากคุณเป็นแขกเพียงคนเดียว คุณจึงสามารถรับประทานได้โดยตรงที่เคาน์เตอร์",
  str_homestory_N26dianying_90060201_23X3_dialog_content = "อะไร คุณคิดว่าฉันจะไปถึงเคาน์เตอร์ได้ไหม!?",
  str_homestory_N26dianying_90060201_23X4_dialog_content = "ฉันไม่รู้จะทำยังไงเหมือนกัน ทั้งหมดที่ฉันทำได้คือขอให้คุณพยายามสูงขึ้น",
  str_homestory_N26dianying_90060201_23X5_dialog_content = "คุณไม่คิดว่าฉันแก่เกินไปที่จะสูงขึ้นเรื่อยๆ เหรอ!?",
  str_homestory_N26dianying_90060201_23X6_dialog_content = "นอกจากนี้ ที่นี่ไม่มีใครเลยจริงๆ! ฉันอยู่ในสถานที่ที่ถูกต้องหรือไม่?",
  str_homestory_N26dianying_90060201_23X7_dialog_content = "ทึ่ง! ค้นหาที่นี่อีกครั้ง อาจจะมี Thorngate Inn อีกแห่ง",
  str_homestory_N26dianying_90060201_23X8_dialog_content = "...",
  str_homestory_N26dianying_90060201_24_dialog_content = "อ้อเข้าใจแล้ว. ทำตามใจปรารถนาแล้ว.",
  str_homestory_N26dianying_90060201_25_dialog_content = "เอาล่ะ เรามาเริ่มภารกิจกันอีกครั้ง...",
  str_homestory_N26dianying_90060201_26_dialog_content = "\"ไปที่ Thorngate Inn และติดต่อกับนักรบลึกลับ\"",
  str_homestory_N26dianying_90060201_27_dialog_content = "\"ความลับมีความสำคัญสูงสุด ดังนั้นนักรบจึงเลือกที่จะปกปิดตัวตนของพวกเขา\"",
  str_homestory_N26dianying_90060201_28_dialog_content = "“ขอเพียงรู้ว่านักรบที่มีปัญหาอยู่ในช่วงชีวิตที่รุ่งเรือง และศิลปะการต่อสู้ของพวกเขาก็ไม่เป็นสองรองใคร”",
  str_homestory_N26dianying_90060201_29_dialog_content = "\"ครั้งหนึ่งที่ Thorngate Inn สั่งไวน์ออสแมนทัสหนึ่งหม้อ แล้วนักรบจะเดินเข้ามาหาคุณ\"",
  str_homestory_N26dianying_90060201_30_dialog_content = "\"หลังจากที่คุณติดต่อได้แล้ว ให้มอบยาอายุวัฒนะให้กับพวกเขา แล้วโลกก็จะสงบสุขอีกครั้ง\"",
  str_homestory_N26dianying_90060201_31_dialog_content = "\"ขอให้โชคดี ฮีโร่ผู้กล้าหาญ!\"",
  str_homestory_N26dianying_90060201_32_dialog_content = "ง่ายพอ! ฉันแค่ต้องหาคนที่ใช่ แล้วภารกิจของฉันก็สำเร็จ!",
  str_homestory_N26dianying_90060201_33_dialog_content = "มาดูกันว่าแขกรับเชิญคนไหนคือนักรบที่ฉันตามหา...",
  str_homestory_N26dianying_90060201_34_dialog_content = "โอ้! อ-นั่นสิ!",
  str_homestory_N26dianying_90060201_35_dialog_content = "แต่งกายด้วยชุดดำทั้งตัว ท่าทางเคร่งขรึมและสงวนท่าที... นักรบระดับปรมาจารย์ที่พยายามทำตัวให้ต่ำต้อย!",
  str_homestory_N26dianying_90060201_36_dialog_content = "เธอต้องเป็นคนที่ฉันตามหา! ตอนนี้สำหรับขั้นตอนต่อไป!",
  str_homestory_N26dianying_90060201_37_dialog_content = "เจ้าของโรงแรม! ขอไวน์ออสมันทัสที่ดีที่สุดของคุณสักหม้อ!",
  str_homestory_N26dianying_90060201_38_dialog_content = "กำลังมา! ฉันจะทิ้งสิ่งนี้ไว้ที่นี่เพื่อคุณ",
  str_homestory_N26dianying_90060201_39_dialog_content = "ทุกวันนี้ไม่ค่อยมีใครดื่มสิ่งนี้ แต่โปรดสนุกด้วย",
  str_homestory_N26dianying_90060201_40_dialog_content = "ไม่เป็นไรอย่างสมบูรณ์ บางอย่างควรเก็บเป็น \"ความลับ\" ใช่ไหม?",
  str_homestory_N26dianying_90060201_41_dialog_content = "ยกโทษให้ฉัน แต่คุณสนใจที่จะดื่มกับฉันไหม",
  str_homestory_N26dianying_90060201_42_dialog_content = "... ไม่ ไปให้พ้นเดี๋ยวนี้",
  str_homestory_N26dianying_90060201_43_dialog_content = "แต่เป็นหม้อไวน์ออสมันตัส! ออสมันตัส! ไม่ค่อยมีใครรู้เรื่องนี้ คุณรู้หรือไม่?",
  str_homestory_N26dianying_90060201_44_dialog_content = "นอกจากนี้... คุณดูเป็นคนประเภทที่ชอบดื่มแบบนี้! ใช่ไหม ถูกต้อง???",
  str_homestory_N26dianying_90060201_45_dialog_content = "... คุณเป็นใครมาบอกความชอบของตัวเอง?",
  str_homestory_N26dianying_90060201_46_dialog_content = "ยังดีกว่า... คุณเป็นใครกันแน่?",
  str_homestory_N26dianying_90060201_47_dialog_content = "จุ๊! ฉันจะบอกคุณ แต่อย่าหยุด ...",
  str_homestory_N26dianying_90060201_48_dialog_content = "ความจริงฉันรู้ว่าเธอเป็นใคร...",
  str_homestory_N26dianying_90060201_49_dialog_content = "คุณทำ?!",
  str_homestory_N26dianying_90060201_50_dialog_content = "ว-เดี๋ยวก่อน! แค่ใจเย็นๆ โอเค?",
  str_homestory_N26dianying_90060201_51_dialog_content = "ถ้าเธอรู้ว่าฉันเป็นใคร...",
  str_homestory_N26dianying_90060201_52_dialog_content = "อะไร ไม่! ฉันหมายความว่าฉันรู้ว่าคุณกำลังปกปิดตัวตนของคุณเป็นความลับ! เป็นเพราะภารกิจของคุณมีความสำคัญสูงสุด จำได้ไหม?",
  str_homestory_N26dianying_90060201_53_dialog_content = "ฉันมาที่นี่เพื่อช่วยคุณ!",
  str_homestory_N26dianying_90060201_54_dialog_content = "ช่วยฉันด้วย...?",
  str_homestory_N26dianying_90060201_55_dialog_content = "ฉันขอถามอะไรได้ไหม",
  str_homestory_N26dianying_90060201_56_dialog_content = "ฉันรู้ว่าศิลปะการต่อสู้ของคุณไม่เป็นสองรองใครในโลก และคุณก็อยู่ในช่วงที่ชีวิตกำลังรุ่งเรือง...",
  str_homestory_N26dianying_90060201_57_dialog_content = "แต่เพื่อปกป้องโลก ยังมีอีกสิ่งหนึ่งที่คุณต้องการ",
  str_homestory_N26dianying_90060201_58_dialog_content = "... คุณกำลังพูดถึงปีศาจอะไร?",
  str_homestory_N26dianying_90060201_59_dialog_content = "แน่นอนยาอายุวัฒนะ! ฉันมีที่นี่สำหรับคุณเท่านั้น!",
  str_homestory_N26dianying_90060201_60_dialog_content = "จ-จริงเหรอเนี่ย?!",
  str_homestory_N26dianying_90060201_61_dialog_content = "สิ่งนี้จะเกิดขึ้นได้จริงหรือ...?",
  str_homestory_N26dianying_90060201_62_dialog_content = "ถูกตัอง! ขออภัยหากฉันมาสาย",
  str_homestory_N26dianying_90060201_63_dialog_content = "ไม่เป็นไร! เพียงแค่ส่งมอบแล้ว!",
  str_homestory_N26dianying_90060201_64_dialog_content = "ด้วยพิษนี้ ในที่สุดฉันก็สามารถสังหารผู้ปกครองเกาะและนำความสงบสุขมาสู่โลกอีกครั้ง!",
  str_homestory_N26dianying_90060201_65_dialog_content = "ด้วยพิษนี้ ในที่สุดฉันก็สามารถสังหารเจ้าเมืองและนำความสงบสุขมาสู่โลกได้อีกครั้ง!",
  str_homestory_N26dianying_90060201_66_dialog_content = "พี-พิษ?!",
  str_homestory_N26dianying_90060201_67_dialog_content = "ในเมื่อคุณรู้อยู่แล้วว่าฉันเป็นใคร ฉันคงไม่มีประโยชน์อะไรที่จะต้องเก็บเป็นความลับ",
  str_homestory_N26dianying_90060201_68_dialog_content = "การเดาของคุณถูกต้อง: ฉันคือมือสังหารระดับโลกที่คุณค้นหามาตลอด",
  str_homestory_N26dianying_90060201_69_dialog_content = "ดะ-เดี๋ยวนะ... ฉันตามหานักฆ่ามาตลอดเลยเหรอ?!",
  str_homestory_N26dianying_90060201_70_dialog_content = "ความพยายามของฉันในการลอบสังหารผู้ปกครองเกาะยังไร้ผล แต่ด้วยพิษนี้...",
  str_homestory_N26dianying_90060201_71_dialog_content = "ความพยายามของฉันในการลอบสังหารเจ้าเมืองนั้นไร้ผลจนถึงตอนนี้ แต่ด้วยพิษนี้...",
  str_homestory_N26dianying_90060201_72_dialog_content = "รีบมาให้ฉัน!",
  str_homestory_N26dianying_90060201_73_dialog_content = "ไม่ไม่ไม่! ฉันเชื่อว่านี่ต้องเป็นการเข้าใจผิดบางอย่าง!",
  str_homestory_N26dianying_90060201_74_dialog_content = "ยาอายุวัฒนะนี้ไม่ใช่ยาพิษแต่อย่างใด! นอกจากนี้...",
  str_homestory_N26dianying_90060201_75_dialog_content = "เราอยู่ในประเทศที่ไม่มีทางออกสู่ทะเลไม่ใช่หรือ “ผู้ปกครองเกาะ” อะไรเอ่ย?!",
  str_homestory_N26dianying_90060201_76_dialog_content = "พอพูดถึงแล้วก็แปลกนิดหน่อย...แถวนี้ไม่เห็นทะเลเลย!",
  str_homestory_N26dianying_90060201_77_dialog_content = "ไม่แน่นอน! เราอยู่ห่างจากชายหาดที่ใกล้ที่สุดหลายพันไมล์!",
  str_homestory_N26dianying_90060201_78_dialog_content = "ต้นซากุระก็แตกต่างกันเช่นกัน... มีผลไม้งอกอยู่บนต้นด้วย",
  str_homestory_N26dianying_90060201_79_dialog_content = "\"ต้นซากุระ\" อะไรนะ?! นั่นคือต้นพีช!",
  str_homestory_N26dianying_90060201_80_dialog_content = "เราอยู่ในทุ่งโล่งไม่ใช่หรือ? “เจ้าเมือง” อะไรเอ่ย?!",
  str_homestory_N26dianying_90060201_81_dialog_content = "คุณมาจากไหนห่า!",
  str_homestory_N26dianying_90060201_82_dialog_content = "ฉันก็ไม่แน่ใจเหมือนกัน... ทั้งหมดที่ฉันรู้ก็คือฉันต้องลงมือสังหารผู้ปกครองเกาะ",
  str_homestory_N26dianying_90060201_83_dialog_content = "ฉันก็ไม่แน่ใจเหมือนกัน... ทั้งหมดที่ฉันรู้คือฉันต้องลงมือสังหารเจ้าเมือง",
  str_homestory_N26dianying_90060201_84_dialog_content = "อย่างน้อยคุณควรพยายามให้ถูกที่!!",
  str_homestory_N26dianying_90060201_85_dialog_content = "คุณรู้อะไรไหม? สมมติว่าบทสนทนานี้ไม่เคยเกิดขึ้น... ขอโทษที่รบกวนคุณ",
  str_homestory_N26dianying_90060201_86_dialog_content = "นอกจากนี้ คราวหน้าลองไปทางตะวันออกดูสิ... สักวันคุณอาจจะได้เห็นมหาสมุทรด้วยซ้ำ",
  str_homestory_N26dianying_90060201_87_dialog_content = "นอกจากนี้ ครั้งหน้าลองไปทางตะวันออก... คุณอาจพบเมืองที่คุณกำลังมองหาอยู่ก็ได้",
  str_homestory_N26dianying_90060201_88_dialog_content = "แต่เดี๋ยวก่อน ยาพิษ...",
  str_homestory_N26dianying_90060201_89_dialog_content = "แค่ลืมมันซะ! ขอให้โชคดีกับภารกิจและวันที่ดี!!",
  str_homestory_N26dianying_90060201_90_dialog_content = "เอ่อ... ไอ้บ้านี่ฉันควรจะไปพบที่ไหนเนี่ย?",
  str_homestory_N26dianying_90060201_91_dialog_content = "เมื่อกี้ฉันผิดใจกับคนๆ นั้น... เธอลึกลับพอตัว แต่ก็ไม่มีอะไรที่กล้าหาญเกี่ยวกับเธอเลย สงสัยต้องลองใหม่ซะแล้ว...",
  str_homestory_N26dianying_90060201_92_dialog_content = "เฮ้... คนๆ นั้นดูกล้าหาญมากสำหรับฉัน!",
  str_homestory_N26dianying_90060201_93_dialog_content = "เจ้าของโรงแรม! ไวน์ออสมันตัสอีกหม้อ!",
  str_homestory_N26dianying_90060201_94_dialog_content = "กำลังมา! ฉันจะทิ้งสิ่งนี้ไว้ที่นี่เพื่อคุณ",
  str_homestory_N26dianying_90060201_95_dialog_content = "ไม่มีผิด... คนนี้ต้องใช่!",
  str_homestory_N26dianying_90060201_96_dialog_content = "ยกโทษให้ฉัน แต่คุณสนใจที่จะดื่มกับฉันไหม",
  str_homestory_N26dianying_90060201_97_dialog_content = "โอ้? ทั้งหมดนี้หมายความว่า.",
  str_homestory_N26dianying_90060201_98_dialog_content = "โอ้? ทั้งหมดนี้หมายความว่า.",
  str_homestory_N26dianying_90060201_99_dialog_content = "ฉันสั่งไวน์ออสมันตัสหนึ่งหม้อ! เจ้าของโรงแรมบอกว่ารสชาติของมันค่อนข้างพิเศษ นี่คือ... สิ่งที่คุณอยากได้?",
  str_homestory_N26dianying_90060201_100_dialog_content = "ได้สิ",
  str_homestory_N26dianying_90060201_101_dialog_content = "ชอบมัน? ฉันรักมัน!",
  str_homestory_N26dianying_90060201_102_dialog_content = "อะไร—?! ดื่มหมดในอึกเดียว!!",
  str_homestory_N26dianying_90060201_103_dialog_content = "การที่คนชอบไวน์ออสมันตัสขนาดนี้...เธอต้องเป็นคนที่ฉันตามหาแน่ๆ!",
  str_homestory_N26dianying_90060201_104_dialog_content = "การที่คนชอบไวน์ออสมันตัสขนาดนี้...เขาต้องเป็นคนที่ฉันตามหาแน่ๆ!",
  str_homestory_N26dianying_90060201_105_dialog_content = "ฟังนะฮีโร่ ฉันรู้ว่าคุณเป็นใครจริงๆ เห็นไหม ฉัน...",
  str_homestory_N26dianying_90060201_106_dialog_content = "จุ๊ๆ! ไม่ดังมาก!",
  str_homestory_N26dianying_90060201_107_dialog_content = "โอ้ใช่! เกือบลืม... \"ความลับสุดยอด\" และทั้งหมดนั้น!",
  str_homestory_N26dianying_90060201_108_dialog_content = "คุณมาติดต่อฉันใช่ไหม ฉันรอมานานมากแล้ว...",
  str_homestory_N26dianying_90060201_109_dialog_content = "ฮ่า ๆ ๆ ๆ! ในที่สุดคุณก็ตัดสินใจที่จะปรากฏตัว!",
  str_homestory_N26dianying_90060201_110_dialog_content = "คุณมาติดต่อฉันใช่ไหม",
  str_homestory_N26dianying_90060201_111_dialog_content = "ท-ถูกต้อง! ขอโทษที่มาสาย!",
  str_homestory_N26dianying_90060201_112_dialog_content = "ไม่คิดอะไรทั้งนั้น ตราบใดที่คุณยังอยากเป็นส่วนหนึ่งของทีมฉัน ฉันจะมองข้ามมันไปสักครั้ง",
  str_homestory_N26dianying_90060201_113_dialog_content = "โอ้ คุณไม่ต้องกังวลเรื่องนั้น!",
  str_homestory_N26dianying_90060201_114_dialog_content = "เอาล่ะ... ยินดีต้อนรับขึ้นเรือ ลูกเรือใหม่ล่าสุดของฉัน!",
  str_homestory_N26dianying_90060201_115_dialog_content = "ซี-ครูว์?!",
  str_homestory_N26dianying_90060201_116_dialog_content = "อย่างแท้จริง. และเนื่องจากคุณเป็นคนแรกที่มาถึง คุณจึงมีสิทธิ์เป็นเพื่อนคนแรกของฉัน",
  str_homestory_N26dianying_90060201_117_dialog_content = "จากนี้ไป คุณสามารถเรียกฉันว่า \"กัปตัน\" ได้",
  str_homestory_N26dianying_90060201_118_dialog_content = "อย่างแท้จริง. และเนื่องจากคุณเป็นคนแรกที่มาถึง คุณจึงมีสิทธิ์เป็นเพื่อนคนแรกของฉัน",
  str_homestory_N26dianying_90060201_119_dialog_content = "จากนี้ไป คุณสามารถเรียกฉันว่า \"กัปตัน\" ได้",
  str_homestory_N26dianying_90060201_120_dialog_content = "เดี๋ยวก่อน เดี๋ยวก่อน... ฉันคิดว่ามีเรื่องเข้าใจผิดอีกแล้ว...",
  str_homestory_N26dianying_90060201_121_dialog_content = "แท้จริงแล้วคุณเป็นกัปตันทีมประเภทไหนกันแน่? เราไม่มีทางออกสู่ทะเลที่นี่โดยสิ้นเชิง และไม่มีเรือลำหนึ่งให้พบเห็นเป็นระยะทางหลายพันไมล์!",
  str_homestory_N26dianying_90060201_122_dialog_content = "คุณก็เข้าใจเหมือนกันใช่ไหม? ที่แห่งนี้กำลังขาดแคลนเรือเดินทะเลอย่างหนัก...",
  str_homestory_N26dianying_90060201_123_dialog_content = "แต่ถ้าฉันสามารถสร้างเรือที่นี่ได้ ฉันจะเป็นกัปตันเรือคนแรกของเมืองทั้งเมือง! เกียรติยศอันทรงเกียรติคุณไม่เห็นด้วยเหรอ?",
  str_homestory_N26dianying_90060201_124_dialog_content = "คุณก็เข้าใจเหมือนกันใช่ไหม? ที่แห่งนี้กำลังขาดแคลนเรือเดินทะเลอย่างหนัก...",
  str_homestory_N26dianying_90060201_125_dialog_content = "แต่ถ้าฉันสามารถสร้างเรือที่นี่ได้ ฉันจะเป็นกัปตันเรือคนแรกของเมืองทั้งเมือง! เกียรติยศอันทรงเกียรติคุณไม่เห็นด้วยเหรอ?",
  str_homestory_N26dianying_90060201_126_dialog_content = "เท่าที่ฉันชื่นชมจิตวิญญาณแห่งการบุกเบิกของคุณ ...",
  str_homestory_N26dianying_90060201_127_dialog_content = "คุณไม่คิดว่าการไม่มีเรือเกี่ยวข้องกับอะไร ฉันไม่รู้... การขาดแคลนน้ำ?!",
  str_homestory_N26dianying_90060201_128_dialog_content = "เฮ้... เรือไม่ต้องการน้ำก็แล่นได้",
  str_homestory_N26dianying_90060201_129_dialog_content = "เฮ้... เรือไม่ต้องการน้ำก็แล่นได้",
  str_homestory_N26dianying_90060201_130_dialog_content = "ไอ้นี่มันหมายความว่าไงวะ!",
  str_homestory_N26dianying_90060201_131_dialog_content = "วางใจได้ ฉันได้พิจารณาคำถามเหล่านี้ทั้งหมดแล้ว",
  str_homestory_N26dianying_90060201_132_dialog_content = "วางใจได้ ฉันได้พิจารณาคำถามเหล่านี้ทั้งหมดแล้ว",
  str_homestory_N26dianying_90060201_133_dialog_content = "จริงหรือ เพราะฉันขอแตกต่าง!",
  str_homestory_N26dianying_90060201_134_dialog_content = "เมื่อมีคนเข้าร่วมทีมของเรามากพอ เราสามารถขอความช่วยเหลือจากอาณาจักรได้! ทุกอย่างจะดีขึ้นเมื่อเราถึงจุดนั้น!",
  str_homestory_N26dianying_90060201_135_dialog_content = "เมื่อมีคนเข้าร่วมทีมของเรามากพอ เราสามารถขอความช่วยเหลือจากอาณาจักรได้! ทุกอย่างจะดีขึ้นเมื่อเราถึงจุดนั้น!",
  str_homestory_N26dianying_90060201_136_dialog_content = "... คุณรู้อะไรไหม? ฉันเพิ่งนึกขึ้นได้ว่าฉันเมาเรือง่ายมาก! นอกจากนี้ ฉันมีธุระอื่นที่ต้องจัดการด้วย!",
  str_homestory_N26dianying_90060201_137_dialog_content = "ฉันจะไปแล้ว!",
  str_homestory_N26dianying_90060201_138_dialog_content = "แต่เดี๋ยวก่อน แล้วการเป็นเพื่อนคนแรกของฉันล่ะ?",
  str_homestory_N26dianying_90060201_139_dialog_content = "แต่เดี๋ยวก่อน แล้วการเป็นเพื่อนคนแรกของฉันล่ะ?",
  str_homestory_N26dianying_90060201_140_dialog_content = "ฉันจะไม่ตัดขาดจากชีวิตที่หวือหวา ฉันสัญญา! ขอให้โชคดี!",
  str_homestory_N26dianying_90060201_141_dialog_content = "เย้... ที่นี่มีคนธรรมดาๆ คนเดียวด้วยเหรอ?!",
  str_homestory_N26dianying_90060201_142_dialog_content = "จะเป็นใครได้อีก...?",
  str_homestory_N26dianying_90060201_143_dialog_content = "ไม่นะ... มีคนเดียวที่ฉันยังไม่ได้ถาม",
  str_homestory_N26dianying_90060201_144_dialog_content = "แต่ไม่ตรงกับคำอธิบายของเควสเลย... ฉันควรทำอย่างไร?",
  str_homestory_N26dianying_90060201_145_dialog_content = "อา ลืมไปเลย... ฉันอยู่ที่นี่แล้ว ดังนั้นฉันอาจลองดูก็ได้",
  str_homestory_N26dianying_90060201_146_dialog_content = "เจ้าของโรงแรม! ขออีกหม้อ!",
  str_homestory_N26dianying_90060201_147_dialog_content = "ดีมาก แต่... คุณรู้ไหมว่านี่เป็นหม้อที่สามของคุณใช่ไหม?",
  str_homestory_N26dianying_90060201_148_dialog_content = "ฉันไม่รู้ว่าคุณชอบไวน์ออสมันตัสมากขนาดนี้",
  str_homestory_N26dianying_90060201_149_dialog_content = "T-พูดตามตรง ฉันยังไม่ได้จิบเลยด้วยซ้ำ...",
  str_homestory_N26dianying_90060201_150_dialog_content = "ขอให้ลูกค้าหน้าตาประหลาดคนนี้เป็นคนที่ฉันตามหา...",
  str_homestory_N26dianying_90060201_151_dialog_content = "ยกโทษให้ฉัน แต่คุณต้องการ -",
  str_homestory_N26dianying_90060201_152_dialog_content = "ในที่สุดคุณก็มาถึงแล้ว!",
  str_homestory_N26dianying_90060201_153_dialog_content = "หา?!",
  str_homestory_N26dianying_90060201_154_dialog_content = "S-ขออภัย การตอบสนองของคุณทำให้ฉันไม่ทันตั้งตัว...",
  str_homestory_N26dianying_90060201_155_dialog_content = "คุณรู้ว่าฉันเป็นใครใช่ไหม?",
  str_homestory_N26dianying_90060201_156_dialog_content = "ฉันทำ? ขอโทษนะ แต่ฉันไม่แน่ใจอะไรอีกแล้ว...",
  str_homestory_N26dianying_90060201_157_dialog_content = "สองคนสุดท้ายที่ฉันเข้าหาคือ... อย่างอื่น",
  str_homestory_N26dianying_90060201_158_dialog_content = "ฉันมาจากอนาคตพันปี!",
  str_homestory_N26dianying_90060201_159_dialog_content = "และคุณก็ไม่ต่างกัน!!!",
  str_homestory_N26dianying_90060201_160_dialog_content = "ฉันติดอยู่ ณ จุดนี้หลังจากเกิดข้อผิดพลาดในการป้อนข้อมูลทำให้เทเลพอร์ตของฉันทำงานผิดปกติขั้นวิกฤต",
  str_homestory_N26dianying_90060201_161_dialog_content = "แต่คุณมาที่นี่เพื่อพาฉันกลับใช่ไหม?",
  str_homestory_N26dianying_90060201_162_dialog_content = "... ฉันไม่เข้าใจแม้แต่คำเดียวที่ออกมาจากปากของคุณในตอนนี้",
  str_homestory_N26dianying_90060201_163_dialog_content = "เดี๋ยวก่อน คุณจะไม่พาฉันกลับไปเวลาของฉันเหรอ ไม่ได้เรื่อง.",
  str_homestory_N26dianying_90060201_164_dialog_content = "อ๊าก! ฉันล้มเหลวโดยสิ้นเชิงในภารกิจของฉัน!",
  str_homestory_N26dianying_90060201_165_dialog_content = "เควส?",
  str_homestory_N26dianying_90060201_166_dialog_content = "เควส? ภารกิจอะไร?",
  str_homestory_N26dianying_90060201_167_dialog_content = "อ้อ ลืมไป... มันไม่สำคัญอีกต่อไปแล้ว",
  str_homestory_N26dianying_90060201_168_dialog_content = "ขออภัย ฉันไม่ใช่คนที่คุณกำลังมองหา",
  str_homestory_N26dianying_90060201_169_dialog_content = "ยังไงก็ต้องถาม... คนจากอนาคตมาทำอะไรในสถานที่แบบนี้?",
  str_homestory_N26dianying_90060201_170_dialog_content = "ในอนาคตอีกพันปี ห้องทดลองของฉันจะตั้งอยู่ในที่แห่งนี้",
  str_homestory_N26dianying_90060201_171_dialog_content = "นั่นเป็นเพราะห้องทดลองของฉันนั่งอยู่ตรงจุดนี้! อีกแค่พันปีข้างหน้าแน่นอน",
  str_homestory_N26dianying_90060201_172_dialog_content = "อย่างไรก็ตาม นักวิจัยเพื่อนของฉันควรจะมาที่นี่เพื่อช่วยฉันในเร็วๆ นี้... เร็วๆ นี้",
  str_homestory_N26dianying_90060201_173_dialog_content = "นั่นเป็นเหตุผลว่าทำไมคุณถึงรอที่นี่มาตลอด? ไม่มีทางอื่นที่จะย้อนเวลากลับไปได้เหรอ?",
  str_homestory_N26dianying_90060201_174_dialog_content = "ฉันขอรออีกพันปีได้ไหม",
  str_homestory_N26dianying_90060201_175_dialog_content = "ไม่เชิง. ฉันไม่สามารถติดต่อเพื่อนร่วมงานได้เลยนับจากนี้",
  str_homestory_N26dianying_90060201_176_dialog_content = "ถ้าฉันติดต่อพวกเขาไม่ได้ ฉันก็ต้องรอจนกว่าห้องทดลองจะถูกสร้างขึ้นอีกครั้ง",
  str_homestory_N26dianying_90060201_177_dialog_content = "คุณจะนั่งที่นี่เป็นเวลาหนึ่งพันปีเหรอ!",
  str_homestory_N26dianying_90060201_178_dialog_content = "ถ้านั่นคือสิ่งที่ต้องทำ ใช่แล้ว",
  str_homestory_N26dianying_90060201_179_dialog_content = "คือ เอ่อ... ต้องใช้ความอดทนอย่างมาก",
  str_homestory_N26dianying_90060201_180_dialog_content = "เฮ้อ... ถ้าฮีโร่ของฉันมีความอดทนขนาดนั้น!",
  str_homestory_N26dianying_90060201_181_dialog_content = "ถึงกระนั้น ฉันไม่โทษพวกเขาที่ไม่ได้อยู่ที่นี่ ถ้ามีอะไร ฉันผิดเองที่มาช้า...",
  str_homestory_N26dianying_90060201_182_dialog_content = "คุณสามารถใช้เวลาอีกพันปีข้างหน้าเพื่อเป็นเพื่อนกับฉันได้เสมอ?",
  str_homestory_N26dianying_90060201_183_dialog_content = "Gee ขอบคุณสำหรับข้อเสนอที่ดี ...",
  str_homestory_N26dianying_90060201_184_dialog_content = "ฉันแค่หวังว่าฉันจะมองโลกในแง่ดีได้เหมือนคุณ...",
  str_homestory_N26dianying_90060201_185_dialog_content = "เฮ้! ฟังนะ เจ้าหมูผู้อิ่มเอมใจ!",
  str_homestory_N26dianying_90060201_186_dialog_content = "ฮะ? เกิดอะไรขึ้นกับการตะโกนข้างนอก?",
  str_homestory_N26dianying_90060201_187_dialog_content = "ภูเขานี้เป็นของฉันคุณได้ยินไหม",
  str_homestory_N26dianying_90060201_188_dialog_content = "ถ้าคุณมีสมองเหลือเฟือ ทิ้งของมีค่าไว้ข้างหลังแล้วหลงทาง! ถ้าไม่ทำ ฉันจะทุบหัวสมองเล็กๆ น้อยๆ ที่คุณมีลงบนพื้น!",
  str_homestory_N26dianying_90060201_189_dialog_content = "โจร?! โอ้นี่มันแย่แล้ว!",
  str_homestory_N26dianying_90060201_190_dialog_content = "ฉันไม่เหมาะกับพวกเขาทั้งหมดในคราวเดียว! ฉันต้องหาทางออกจากที่นี่...",
  str_homestory_N26dianying_90060201_191_dialog_content = "ให้ตายเถอะ... ถ้าฉันสู้กับพวกมัน ผ้าคลุมของฉันคงปลิวไปแล้ว ได้เวลาถอย...",
  str_homestory_N26dianying_90060201_192_dialog_content = "นั่นเร็วมาก!!",
  str_homestory_N26dianying_90060201_193_dialog_content = "โอ้เยี่ยม! แค่มองไปที่ใบหน้าที่กระตือรือร้นเหล่านั้น! พวกมันต้องมาเป็นลูกเรือของฉันแน่ๆ!",
  str_homestory_N26dianying_90060201_194_dialog_content = "ฉันควรจะไปทักทายพวกเขา!",
  str_homestory_N26dianying_90060201_195_dialog_content = "โอ้เยี่ยม! แค่มองไปที่ใบหน้าที่กระตือรือร้นเหล่านั้น! พวกมันต้องมาเป็นลูกเรือของฉันแน่ๆ!",
  str_homestory_N26dianying_90060201_196_dialog_content = "ฉันควรจะไปทักทายพวกเขา!",
  str_homestory_N26dianying_90060201_197_dialog_content = "G-กลับเข้ามาที่นี่! คุณไม่ได้จับความเป็นจริงแม้แต่น้อย!",
  str_homestory_N26dianying_90060201_198_dialog_content = "สิ่งนี้ไม่ได้ผล... ฉันปล่อยให้กลุ่มโจรเข้ายึดครองพื้นที่ในอนาคตของห้องทดลองไม่ได้",
  str_homestory_N26dianying_90060201_199_dialog_content = "ฉันจะไปกำจัดพวกมัน",
  str_homestory_N26dianying_90060201_200_dialog_content = "โดยตัวคุณเอง? แต่ดูเหมือนว่ามีพวกเขาอยู่มากมาย!",
  str_homestory_N26dianying_90060201_201_dialog_content = "ว้าว... ก็อย่างนั้นแหละ เหลือแค่เจ้าของโรงแรมและตัวฉันเอง...",
  str_homestory_N26dianying_90060201_202_dialog_content = "นี่ไม่ใช่วันของฉัน... อันดับแรก ฉันติดต่อคนที่เหมาะสมไม่ได้ จากนั้นเราก็ถูกโจมตีโดยกลุ่มโจร...",
  str_homestory_N26dianying_90060201_203_dialog_content = "ฉันยังต้องจ่ายแท็บของฉันไหมหากเราตายกันหมด?",
  str_homestory_N26dianying_90060201_204_dialog_content = "คุณเลิกค้นหาแล้วใช่ไหม",
  str_homestory_N26dianying_90060201_205_dialog_content = "ใช่... ฉันคงถึงเวลาที่ต้องยอมรับชะตากรรมของฉันแล้ว...",
  str_homestory_N26dianying_90060201_206_dialog_content = "W-เดี๋ยวก่อน คุณรู้เรื่องนั้นได้ยังไง!",
  str_homestory_N26dianying_90060201_207_dialog_content = "ภารกิจของฉันควรจะเป็นความลับสุดยอด!",
  str_homestory_N26dianying_90060201_208_dialog_content = "คนที่คุณตามหาอยู่ที่นี่มาตลอด...",
  str_homestory_N26dianying_90060201_209_dialog_content = "แต่นั่นไม่ได้ทำให้พวกเขาเป็นลูกค้าเสมอไป",
  str_homestory_N26dianying_90060201_210_dialog_content = "เดี๋ยวก่อน คุณไม่ได้หมายความว่า...",
  str_homestory_N26dianying_90060201_211_dialog_content = "มันอาจจะเป็น...?!",
  str_homestory_N26dianying_90060201_212_dialog_content = "คุณเป็นนักรบที่ฉันควรจะพบหรือไม่!",
  str_homestory_N26dianying_90060201_213_dialog_content = "ไม่มีทาง! นี้ไม่ได้!",
  str_homestory_N26dianying_90060201_214_dialog_content = "บุคคลในภารกิจควรจะเป็น \"ในช่วงชีวิตของพวกเขา\"! ศิลปะการต่อสู้ของพวกเขานั้นไม่เป็นสองรองใคร! แต่คุณ...",
  str_homestory_N26dianying_90060201_215_dialog_content = "หน้าโทรมมาก...แถมต้องนั่งรถเข็น! คุณจะเป็นคนที่ฉันตามหาได้ยังไง!",
  str_homestory_N26dianying_90060201_216_dialog_content = "เฮอะ บรรยายเพ้อฝันดีจัง...แต่ก็เข้ากันนะ นักรบที่คุณมาที่นี่เพื่อหาไม่ใช่ใครอื่นนอกจากคุณอย่างแท้จริง",
  str_homestory_N26dianying_90060201_217_dialog_content = "เพียงแต่... คุณมาช้าเกินไป",
  str_homestory_N26dianying_90060201_218_dialog_content = "ช้าไปสิบปีจริงๆ!",
  str_homestory_N26dianying_90060201_219_dialog_content = "สิบปี?!",
  str_homestory_N26dianying_90060201_220_dialog_content = "อะไร?!?",
  str_homestory_N26dianying_90060201_221_dialog_content = "ขาของฉันได้รับบาดเจ็บสาหัสเมื่อสิบปีก่อน ฉันจึงมาซ่อนตัวที่นี่ ฉันกำลังรอให้ฮีโร่นำยาอายุวัฒนะมาให้ฉัน",
  str_homestory_N26dianying_90060201_222_dialog_content = "แต่รอนานแค่ไหน...ฮีโร่คนนั้นก็ไม่เคยมา",
  str_homestory_N26dianying_90060201_223_dialog_content = "มีการเปลี่ยนแปลงมากมายในช่วงสิบปีที่ผ่านมา ฉันบังคับตัวเองให้ดื่มไวน์ออสมันทัสทุกวัน และในที่สุดฉันก็ได้ลิ้มรสมัน",
  str_homestory_N26dianying_90060201_224_dialog_content = "เพราะยาอายุวัฒนะไม่เคยมา ขาของฉันจึงค่อยๆ แย่ลง และฉันต้องนั่งรถเข็น",
  str_homestory_N26dianying_90060201_225_dialog_content = "ฉันกลายเป็นเพื่อนสนิทกับเจ้าของคนก่อนของโรงแรมนี้ และเมื่อเขาเสียชีวิตในที่สุด... ฉันรู้สึกประหลาดใจที่รู้ว่าเขาได้มอบความไว้วางใจให้กับฉัน",
  str_homestory_N26dianying_90060201_226_dialog_content = "ฉันไม่เคยคิดเลยว่าหลังจากเวลานี้ คุณยังคงปรากฏตัว",
  str_homestory_N26dianying_90060201_227_dialog_content = "โอ้ เอ่อ...",
  str_homestory_N26dianying_90060201_228_option_content = "ขอโทษอย่างจริงใจ",
  str_homestory_N26dianying_90060201_229_dialog_content = "อย่ายืนอยู่ตรงนั้น! ขอโทษเดี๋ยวนี้!",
  str_homestory_N26dianying_90060201_230_dialog_content = "F-ยกโทษให้ฉัน ฮีโร่ผู้กล้าหาญ! จากก้นบึ้งของหัวใจ ฉันขอโทษจริงๆ!",
  str_homestory_N26dianying_90060201_231_dialog_content = "ฉัน-ถ้าเพียงแต่ฉันไม่อืดขนาดนั้น...",
  str_homestory_N26dianying_90060201_232_dialog_content = "คุณเป็นสิบปี \"อืด\"? คุณไม่คิดว่านั่นเป็นการพูดน้อยไปหน่อยเหรอ?",
  str_homestory_N26dianying_90060201_233_dialog_content = "ทั้งหมดเป็นความผิดของฉันเอง... ฉันวางม้วนเควสผิดตำแหน่งในบ้านของฉัน...",
  str_homestory_N26dianying_90060201_234_dialog_content = "จนกระทั่งฉันเริ่มเก็บข้าวของเพื่อย้ายออก ในที่สุดฉันก็พบมัน ปัญหาเดียวคือฉันลืมไปว่าคำขอนั้นอายุเท่าไหร่...",
  str_homestory_N26dianying_90060201_235_dialog_content = "ทุกอย่างปกติดี. หากสิ่งนี้เกิดขึ้นเมื่อไม่กี่ปีก่อน ฉันคงหัวเสีย แต่ตอนนี้... ฉันอดไม่ได้ที่จะคิดว่ามันน่าขบขัน น่าหัวเราะด้วยซ้ำ",
  str_homestory_N26dianying_90060201_236_dialog_content = "คุณดูเหมือนจะจริงใจอย่างสมบูรณ์ ดังนั้นฉันจะไม่ติดตามเรื่องนี้ วันเวลาแห่งการผจญภัยของฉันยังล้าหลังอยู่มาก ขอเพียงใช้ชีวิตที่เหลืออยู่อย่างสงบสุข",
  str_homestory_N26dianying_90060201_237_dialog_content = "ถึงกระนั้น ฉันยังทิ้งเรื่องค้างคาไว้สองสามเรื่องในอดีต... ถ้าเธอต้องการจะแก้ไขจริง ๆ เธอช่วยดูแลแทนฉันได้ไหม?",
  str_homestory_N26dianying_90060201_238_dialog_content = "จริงหรือ แน่นอน ฉันเต็มใจช่วย!",
  str_homestory_N26dianying_90060201_239_dialog_content = "คู่หูเก่าของฉันจากวันผจญภัยของฉันอาศัยอยู่ใกล้ ๆ เช่นเดียวกับตัวผม เขาเลือกที่จะซ่อนตัวตนของเขาไว้ และทำงานในตลาด",
  str_homestory_N26dianying_90060201_240_dialog_content = "ฉันมีจดหมายถึงเขา และฉันต้องการให้คุณทำภารกิจของฉันให้สำเร็จด้วยการส่งไปให้เขา",
  str_homestory_N26dianying_90060201_241_dialog_content = "เข้าใจแล้ว! ฉันต้องพบกับผู้ติดต่อที่ไม่ระบุชื่อรายอื่นใช่ไหม ตอนนี้ฉันมีประสบการณ์กับภารกิจประเภทนี้แล้ว!",
  str_homestory_N26dianying_90060201_242_dialog_content = "ฉันหวังอย่างนั้นอย่างแน่นอน",
  str_homestory_N26dianying_90060201_243_dialog_content = "ไม่มีที่ว่างสำหรับ \"การล่าช้า\" ของคุณอีกต่อไปเมื่อต้องส่งจดหมายฉบับนี้",
  str_homestory_N26dianying_90060201_244_dialog_content = "บุคคลดังกล่าวอายุมากกว่าฉันด้วยซ้ำ ฉันสงสัยว่าเขาจะมีชีวิตอยู่เพื่อดูอีกสิบปีผ่านไป",
  str_homestory_N26dianying_90060201_245_option_content = "สร้างข้อแก้ตัว",
  str_homestory_N26dianying_90060201_246_dialog_content = "คุณลืม? คิดถึงเหตุผลที่คุณมาสาย!",
  str_homestory_N26dianying_90060201_247_dialog_content = "โอ้ใช่! เป็นเพราะฉันมีภารกิจมากเกินไป!",
  str_homestory_N26dianying_90060201_248_dialog_content = "คุณเห็นไหมว่า ด้วยแผ่นดินที่อยู่ในสภาพระส่ำระสายเช่นนี้ ฉันมีฮีโร่มากมายที่ยื่นมือเข้ามาหาฉันจนไม่สามารถติดตามพวกเขาได้ทั้งหมด!",
  str_homestory_N26dianying_90060201_249_dialog_content = "บางคนอยู่ใกล้ความตายแล้ว ฉันจึงต้องจัดลำดับความสำคัญก่อนหลัง",
  str_homestory_N26dianying_90060201_250_dialog_content = "คุณ-น่าเสียดาย... นั่นเป็นเหตุผลว่าทำไมฉันถึงใช้เวลานานมากในการตามหาคุณ",
  str_homestory_N26dianying_90060201_251_dialog_content = "อย่างนั้นเหรอ? ไม่นึกเลยว่าจะมีฮีโร่มากมายที่ตกทุกข์ได้ยาก...",
  str_homestory_N26dianying_90060201_252_dialog_content = "ทำไมคุณไม่บอกชื่อพวกเขาสักสองสามชื่อให้ฉัน ใครจะรู้ บางทีฉันอาจรู้จักพวกเขาในสมัยของฉัน",
  str_homestory_N26dianying_90060201_253_dialog_content = "ฉันจะรู้สึกดีขึ้นมากเมื่อรู้ว่าสหายเก่าของฉันได้รับการดูแล แม้ว่าจะต้องออกค่าใช้จ่ายเองก็ตาม",
  str_homestory_N26dianying_90060201_254_dialog_content = "S-แน่นอน เดี๋ยวก่อน...",
  str_homestory_N26dianying_90060201_255_dialog_content = "ใช้เวลาทั้งหมดที่คุณต้องการ ท้ายที่สุด ฉันรอคุณสิบปี... ฉันรอได้อีกสิบปี",
  str_homestory_N26dianying_90060201_256_dialog_content = "ถ้าคุณจำชื่อพวกเขาไม่ได้ บางทีฉันอาจจะแนะนำคุณให้รู้จักได้บ้าง ที่อาจทำให้ความจำของคุณกระตุก...",
  str_homestory_N26dianying_90060201_257_dialog_content = "ฉัน-แนะนำฉันให้พวกเขารู้จัก?",
  str_homestory_N26dianying_90060201_258_dialog_content = "ถูกต้อง แม้ว่าฉันไม่ควรเรียกพวกเขาว่า \"ฮีโร่\" อีกต่อไป เห็นไหมว่าบางคนเริ่มเดินผิดทางในอดีต...",
  str_homestory_N26dianying_90060201_259_dialog_content = "อันที่จริง ฉันเชื่อว่าพวกเขาสองสามคนกำลังยืนอยู่หน้าประตูบ้านของฉัน รอโอกาสที่จะได้พูดคุยเกี่ยวกับวันเก่าๆ ที่ดี",
  str_homestory_N26dianying_90060201_260_dialog_content = "ไม่ได้หมายถึงโจร...รึเปล่า?!",
  str_homestory_N26dianying_90060201_261_dialog_content = "ไม่ ได้โปรด! ฉันไม่อยากเจอพวกเขา!",
  str_homestory_N26dianying_90060201_262_dialog_content = "ฉันคิดผิดแล้ว คุณเจ้าของโรงแรม! ฉันขอโทษ!!!",
  str_homestory_N26dianying_90060201_263_option_content = "ทำภารกิจให้สำเร็จ",
  str_homestory_N26dianying_90060201_264_dialog_content = "อย่าลืม! คุณยังมีภารกิจที่ต้องทำ!",
  str_homestory_N26dianying_90060201_265_dialog_content = "ตอนนี้ไม่สำคัญแล้ว! ฉันนำยาอีลิกเซอร์มาให้คุณแล้ว ฮีโร่ผู้กล้าหาญ!",
  str_homestory_N26dianying_90060201_266_dialog_content = "และในขณะที่ฉันส่งของช้าไปหน่อย... ในที่สุดภารกิจของฉันก็เสร็จสมบูรณ์!",
  str_homestory_N26dianying_90060201_267_dialog_content = "\"สายไปหน่อย\" คุณพูด?",
  str_homestory_N26dianying_90060201_268_dialog_content = "ไม่นึกเลยว่าเวลาหนึ่งทศวรรษช่างน้อยนิดนัก...",
  str_homestory_N26dianying_90060201_269_dialog_content = "ฉันขอโทษจริงๆ เรื่องนั้น... ฉันแค่วางม้วนเควสผิดที่ในบ้านของฉัน...",
  str_homestory_N26dianying_90060201_270_dialog_content = "จนกระทั่งฉันเริ่มเก็บข้าวของเพื่อย้ายออก ในที่สุดฉันก็พบมัน ปัญหาเดียวคือฉันลืมไปว่าคำขอนั้นอายุเท่าไหร่...",
  str_homestory_N26dianying_90060201_271_dialog_content = "ไม่ว่าในกรณีใดฉันนำมันมาทั้งหมดดังนั้นนี่เลย ใครจะไปรู้ มันอาจทำให้ขาของคุณยกขึ้นได้!",
  str_homestory_N26dianying_90060201_272_dialog_content = "ด้วยวิธีนี้ ฉันสามารถส่งภารกิจของฉันเมื่อฉันกลับมา",
  str_homestory_N26dianying_90060201_273_dialog_content = "ฉันไม่ต้องการมันอีกแล้ว ขาของฉันพังไปแล้ว และไม่มีน้ำอมฤตสักเท่าไรที่จะรักษามันได้",
  str_homestory_N26dianying_90060201_274_dialog_content = "แค่เก็บไว้ใช้เอง คุณอาจจะต้องใช้มันในสักวันหนึ่ง",
  str_homestory_N26dianying_90060201_275_dialog_content = "ฉันไม่รู้เรื่องนั้น... อีกอย่าง ฉันส่งเควสไม่ได้ถ้าคุณไม่รับ",
  str_homestory_N26dianying_90060201_276_dialog_content = "บังเอิญเราถูกล้อมด้วยกลุ่มโจรกระหายเลือด...",
  str_homestory_N26dianying_90060201_277_dialog_content = "ฉันคิดว่าคุณอาจต้องการมันมากกว่าที่คุณคิดในไม่ช้านี้",
  str_homestory_N26dianying_90060201_278_dialog_content = "อะไร?!?",
  str_homestory_N26dianying_90060201_279_dialog_content = "ไม่ ได้โปรด! ช่วยฉันด้วยฮีโร่ผู้ยิ่งใหญ่และเมตตา!",
  str_homestory_N26dianying_90060201_280_dialog_content = "เจ้าของโรงแรม! ขอไวน์ออสมันทัสที่ดีที่สุดของคุณสักหม้อ!",
  str_homestory_N26dianying_90060201_281_dialog_content = "ขออภัย เราหมดแล้ว",
  str_homestory_N26dianying_90060201_282_dialog_content = "อะไร “หมดแล้ว”?!",
  str_homestory_N26dianying_90060201_283_dialog_content = "ถูกตัอง. ตอนนี้ฉันไม่มีของในมือสักหยด",
  str_homestory_N26dianying_90060201_284_dialog_content = "คุณจะหมดในเวลาเช่นนี้ได้อย่างไร? ตอนนี้ทุกอย่างพังทลาย!",
  str_homestory_N26dianying_90060201_285_dialog_content = "ฉันสามารถส่งบางอย่างได้เสมอ ถ้าคุณต้องการ",
  str_homestory_N26dianying_90060201_286_dialog_content = "ถ้าวันนี้คุณตั้งใจจะดื่มไวน์แบบนี้ ผมสามารถสั่งจากร้านข้างเคียงได้ จะใช้เวลาสักครู่ แต่สามารถทำได้",
  str_homestory_N26dianying_90060201_287_dialog_content = "จ-จริงเหรอ",
  str_homestory_N26dianying_90060201_288_dialog_content = "ได้เลย ฉันรอได้!",
  str_homestory_N26dianying_90060201_289_dialog_content = "ไวน์ออสมันตัสนี้มีรสชาติที่เป็นเอกลักษณ์มาก ทุกวันนี้ไม่ค่อยมีใครดื่มสิ่งนี้ แต่โปรดสนุกด้วย",
  str_homestory_N26dianying_90060201_290_dialog_content = "ถึงกระนั้น ฉันก็รู้สึกดีที่ได้เห็นคนอื่นชื่นชมเครื่องดื่มที่ฉันชื่นชอบ",
  str_homestory_N26dianying_90060201_291_dialog_content = "เพียงแค่วางไว้ด้านข้างเมื่อมาถึงที่นี่ โปรด ทุกอย่างจะพังถ้าไม่มีหม้อ...",
  str_homestory_N26dianying_90060201_292_dialog_content = "<color=#e8d9bb>ก๊อก ก๊อก ก๊อก!</color>",
  str_homestory_N26dianying_90060201_293_dialog_content = "มีคนอยู่ที่ประตู! พวกเขานำไวน์ออสแมนทัสมาด้วยหรือไม่?",
  str_homestory_N26dianying_90060201_294_dialog_content = "จุ๊ๆ! เสียงนั้น...",
  str_homestory_N26dianying_90060201_295_dialog_content = "เฮ้! ฟังนะ เจ้าหมูผู้อิ่มเอมใจ!",
  str_homestory_N26dianying_90060201_296_dialog_content = "ภูเขานี้เป็นของฉันคุณได้ยินไหม",
  str_homestory_N26dianying_90060201_297_dialog_content = "ถ้าคุณมีสมองเหลือเฟือ ทิ้งของมีค่าไว้ข้างหลังแล้วหลงทาง! ถ้าไม่ทำ ฉันจะทุบหัวสมองเล็กๆ น้อยๆ ที่คุณมีลงบนพื้น!",
  str_homestory_N26dianying_90060201_298_dialog_content = "โจร? ตอนนี้ตลอดเวลา?!",
  str_homestory_N26dianying_90060201_299_dialog_content = "ให้ตายเถอะ... ถ้าฉันสู้กับพวกมัน ผ้าคลุมของฉันคงปลิวไปแล้ว ได้เวลาถอย...",
  str_homestory_N26dianying_90060201_300_dialog_content = "โอ้เยี่ยม! ฉันจะไปทักทายพวกเขา!",
  str_homestory_N26dianying_90060201_301_dialog_content = "โอ้เยี่ยม! ฉันจะไปทักทายพวกเขา!",
  str_homestory_N26dianying_90060201_302_dialog_content = "กำจัดพวกเขาทั้งหมด",
  str_homestory_N26dianying_90060201_303_dialog_content = "โชคไม่ดี ดูเหมือนว่าโรงเตี๊ยมต่ำต้อยของฉันกำลังจะถูกกลุ่มโจรปล้นสะดม",
  str_homestory_N26dianying_90060201_304_dialog_content = "ทีนี้ ถ้าเจ้าจะใจดีหนีออกทางด้านหลังล่ะก็...",
  str_homestory_N26dianying_90060201_305_dialog_content = "ฉันก็อยากจะหนีไปด้วยชีวิตของฉันและทั้งหมด...",
  str_homestory_N26dianying_90060201_306_dialog_content = "แต่ภารกิจของฉันล่ะ?!",
  str_homestory_N26dianying_90060301_1_dialog_content = "เปลวเพลิงแห่งสงครามได้เผาผลาญโลกของเรามาเป็นเวลาหลายปีแล้ว... ในแต่ละวันที่ผ่านไป การต่อสู้กับ Eclipsites ของเราดูเหมือนจะสิ้นหวังมากขึ้นเรื่อยๆ",
  str_homestory_N26dianying_90060301_2_dialog_content = "มีเพียง Heavenly Blade ที่สาบสูญไปนานซึ่งเป็นอาวุธศักดิ์สิทธิ์และทรงพลังเท่านั้นที่สามารถยุติความขัดแย้งและนำความสงบสุขมาสู่โลกได้อีกครั้ง",
  str_homestory_N26dianying_90060301_3_dialog_content = "... หรือตำนานกล่าวว่า ใช่ไหม ผู้รับใช้ที่ซื่อสัตย์ของฉัน",
  str_homestory_N26dianying_90060301_4_dialog_content = "<size=45>ใช่เจ้านายของฉัน!</size>",
  str_homestory_N26dianying_90060301_5_dialog_content = "หูย! เงียบเสียงลง คนโง่!",
  str_homestory_N26dianying_90060301_6_dialog_content = "อะแฮ่ม... ในฐานะทูตของ Dragonscorch พลังที่ทรงพลังที่สุดในแผ่นดิน ฉันมีเหตุผลที่จะเรียกคุณมาที่นี่ในวันนี้",
  str_homestory_N26dianying_90060301_7_dialog_content = "แม้จะเพิ่งเข้าร่วมกลุ่มของเราไม่นาน แต่คุณก็ได้พิสูจน์ตัวเองแล้วว่าเป็นผู้รับใช้ที่ภักดีและมีความสามารถ",
  str_homestory_N26dianying_90060301_8_dialog_content = "ในตอนนี้ ตำนานยังกล่าวอีกว่ามีผู้พบเห็น Heavenly Blade ครั้งสุดท้ายในหมู่บ้านแห่งมังกร จากที่ฉันเข้าใจ คุณก็มาจากหมู่บ้านเดียวกันใช่ไหม",
  str_homestory_N26dianying_90060301_9_dialog_content = "<size=45>ใช่เจ้านายของฉัน!</size>",
  str_homestory_N26dianying_90060301_10_dialog_content = "ยอดเยี่ยม... ถ้าอย่างนั้นฉันขอมอบหน้าที่อันศักดิ์สิทธิ์ให้กับคุณ: กลับไปที่ Village of Dragons และค้นหา Heavenly Blade แทนฉัน",
  str_homestory_N26dianying_90060301_11_dialog_content = "วางใจได้ ท่านลอร์ด ข้าจะไม่ทำให้ท่านผิดหวัง!",
  str_homestory_N26dianying_90060301_12_dialog_content = "ตอนนี้เป็นเวลา 11:15 ในตอนเช้า... ตั้งแต่ตอนนี้ คุณมีเวลาสามวันในการหาใบมีดและนำมันมาให้ฉัน",
  str_homestory_N26dianying_90060301_13_dialog_content = "(เดี๋ยวนะ... เขาพูดว่า \"11:15\" เหรอ!)",
  str_homestory_N26dianying_90060301_14_dialog_content = "เอ่อ นายท่าน? ฉัน เอ่อ... ฉันเพิ่งนึกขึ้นได้ว่าฉันยังต้องแพ็คเสบียงก่อนที่จะออกไปทำภารกิจอันสูงส่งของฉัน!",
  str_homestory_N26dianying_90060301_15_dialog_content = "ดีมากแล้ว ดูเสบียงของคุณและเดินทางไป แต่ทำให้เร็วเข้า!",
  str_homestory_N26dianying_90060301_16_dialog_content = "หอบ หอบ หอบ...",
  str_homestory_N26dianying_90060301_17_dialog_content = "เอ็มมาสเตอร์! ขออภัยในความล่าช้าเล็กน้อย!",
  str_homestory_N26dianying_90060301_18_dialog_content = "\"เล็กน้อย\" คุณพูด? คุณมาสายสามสิบนาที",
  str_homestory_N26dianying_90060301_19_dialog_content = "เฮ้อ... ไม่เป็นไรหรอก ฉันเรียกคุณวันนี้เพราะฉันต้องการความช่วยเหลือจากคุณในเรื่องที่สำคัญที่สุด",
  str_homestory_N26dianying_90060301_20_dialog_content = "แน่นอน คุณเคยได้ยินตำนานของ Heavenly Blade หรือไม่? \"ไฟแห่งสงครามได้เผาผลาญโลกของเรามาเป็นเวลาหลายปีแล้ว...\"",
  str_homestory_N26dianying_90060301_21_dialog_content = "นายท่าน เป็นไปได้ไหมว่า... ท่านต้องการให้ข้าไปที่ Village of Dragons เพื่อค้นหา Heavenly Blade ด้วย?",
  str_homestory_N26dianying_90060301_22_dialog_content = "ถูกต้อง. ด้วยการออกตามหา Heavenly Blade ฝ่าย Zakura จะนำความสงบเรียบร้อยมาสู่โลกที่วุ่นวายนี้ และทำให้สถานที่ของมันแข็งแกร่งขึ้นในฐานะกองกำลังที่ทรงพลังที่สุดที่มีอยู่",
  str_homestory_N26dianying_90060301_23_dialog_content = "เดี๋ยวก่อน... คุณหมายถึงอะไร \"ยัง\"?",
  str_homestory_N26dianying_90060301_24_dialog_content = "โอ้! N-ไม่มีอะไร นายท่าน!",
  str_homestory_N26dianying_90060301_25_dialog_content = "(หากนักการทูตจากทั้งสองฝ่ายพบว่าฉันกำลังทำภารกิจเดียวกันเพื่อพวกเขา...)",
  str_homestory_N26dianying_90060301_26_dialog_content = "(ฉันจะดีเท่ากับตาย!)",
  str_homestory_N26dianying_90060301_27_dialog_content = "ในขณะที่คุณยังขาดประสบการณ์ แหล่งข้อมูลของฉันบอกฉันว่าใบมีดสามารถพบได้ที่ไหนสักแห่งในบ้านเกิดของคุณ หมู่บ้านแห่งมังกร คุณเป็นคนเดียวที่ฉันไว้ใจได้กับภารกิจนี้",
  str_homestory_N26dianying_90060301_28_dialog_content = "<size=45>ใช่เจ้านายของฉัน!</size>",
  str_homestory_N26dianying_90060301_29_dialog_content = "H-อย่างไรก็ตาม ฉันยังมีเรื่องที่จะปรึกษากับสหายของฉันก่อนออกเดินทาง...",
  str_homestory_N26dianying_90060301_30_dialog_content = "ดีมาก แต่พยายามทำให้สั้น อ้อ อย่าลืมตรวจสอบสภาพอากาศให้ฉันก่อนออกเดินทางด้วย",
  str_homestory_N26dianying_90060301_31_dialog_content = "หอบ หอบ หอบ...",
  str_homestory_N26dianying_90060301_32_dialog_content = "M-เจ้านายของฉัน! วันนี้อากาศดี เหมาะแก่การฝึกทหารของคุณ!",
  str_homestory_N26dianying_90060301_33_dialog_content = "อืม? ฉันจำไม่ได้ว่าขอรายงานสภาพอากาศจากคุณ?",
  str_homestory_N26dianying_90060301_34_dialog_content = "(โอ้ อึ! ลอร์ดผิด!)",
  str_homestory_N26dianying_90060301_35_dialog_content = "ถ้าเตรียมตัวเสร็จแล้วก็ออกเดินทางทันที! หากคุณทำสำเร็จ รางวัลของคุณจะมากมาย!",
  str_homestory_N26dianying_90060301_36_dialog_content = "อ้อ ถ้าเธอบังเอิญเห็นดอกทานตะวันบานระหว่างทางล่ะก็ หาทางส่งข่าวมาที่ฉันสิ เข้าใจไหม?",
  str_homestory_N26dianying_90060301_37_dialog_content = "ใช่เจ้านายของฉัน! ฉันจะออกไปทันที!",
  str_homestory_N26dianying_90060301_38_dialog_content = "หอบ หอบ หอบ...",
  str_homestory_N26dianying_90060301_39_dialog_content = "ฉันกลับมาแล้ว นายท่าน! ดอกทานตะวันบานเต็มเมล็ด! สามารถเก็บเกี่ยวได้ตลอดเวลาเพื่อปันส่วนทหาร!",
  str_homestory_N26dianying_90060301_40_dialog_content = "อืม? แล้วฉันขอรายงานเรื่องดอกทานตะวันเมื่อไหร่กันแน่?",
  str_homestory_N26dianying_90060301_41_dialog_content = "โอ้ และในระหว่างการเดินทางของเจ้า หากเจ้าสังเกตเห็นว่าต้นอ้อสูงใหญ่ขึ้น จงหาทางส่งข่าวถึงข้า เข้าใจไหม?",
  str_homestory_N26dianying_90060301_42_dialog_content = "ใช่เจ้านายของฉัน! ฉันจะออกไปทันที!",
  str_homestory_N26dianying_90060301_43_dialog_content = "หอบ หอบ หอบ...",
  str_homestory_N26dianying_90060301_44_dialog_content = "ฉันกลับมาแล้ว นายท่าน! อ้อตอนนี้ทั้งสูงและหนาแน่น เหมาะสำหรับการปกปิดการโจมตีของศัตรูของคุณ!",
  str_homestory_N26dianying_90060301_45_dialog_content = "โอ้? และเมื่อไหร่ที่ฉันขอรายงานเกี่ยวกับกก?",
  str_homestory_N26dianying_90060301_46_dialog_content = "โอ้ และในระหว่างการเดินทางของเจ้า ถ้าเจ้าสังเกตเห็นว่าทุ่งข้าวสาลีสุกเต็มที่แล้ว จงหาทางส่งข่าวถึงข้า เข้าใจไหม?",
  str_homestory_N26dianying_90060301_47_dialog_content = "ใช่เจ้านายของฉัน! ฉันจะออกไปทันที!",
  str_homestory_N26dianying_90060301_48_dialog_content = "หอบ หอบ หอบ...",
  str_homestory_N26dianying_90060301_49_dialog_content = "ฉันกลับมาแล้ว นายท่าน! ทุ่งข้าวสาลีเต็มแล้วพร้อมเก็บเกี่ยว! ทหารจะได้กินดีในฤดูหนาวนี้!",
  str_homestory_N26dianying_90060301_50_dialog_content = "โอ้? และเมื่อไหร่ที่ฉันขอรายงานเกี่ยวกับทุ่งข้าวสาลี?",
  str_homestory_N26dianying_90060301_50X1_dialog_content = "อ้อ แล้วระหว่างเดินทาง ถ้าเจอคนน่าสงสัย ก็หาทางส่งข่าวมาสิ เข้าใจไหม?",
  str_homestory_N26dianying_90060301_50X2_dialog_content = "ใช่เจ้านายของฉัน! ฉันจะออกไปทันที!",
  str_homestory_N26dianying_90060301_50X3_dialog_content = "หอบ หอบ หอบ...",
  str_homestory_N26dianying_90060301_50X4_dialog_content = "ฉันกลับมาแล้ว นายท่าน! ไม่มีคนน่าสงสัยอยู่ใกล้ๆ เรามาเริ่มเตรียมการฝึกกันได้เลย!",
  str_homestory_N26dianying_90060301_50X5_dialog_content = "อืม? ฉันจำไม่ได้ว่าขอให้คุณรายงานสถานการณ์ใกล้เคียงให้ฉันทราบ!",
  str_homestory_N26dianying_90060301_51_dialog_content = "ไม่อีกแล้ว!!)",
  str_homestory_N26dianying_90060301_52_dialog_content = "หากคุณกล่าวคำอำลากับเพื่อนเสร็จแล้ว ให้รีบไปที่ Village of Dragons คุณจะมีความกตัญญูนิรันดร์ของฉันหากคุณประสบความสำเร็จในภารกิจของคุณ",
  str_homestory_N26dianying_90060301_53_dialog_content = "ใช่เจ้านายของฉัน! ฉันจะออกไปทันที!",
  str_homestory_N26dianying_90060301_54_dialog_content = "(ท่านลอร์ด ท่านเป็นทั้งนักปราชญ์และผู้มีอำนาจ... โปรดยกโทษให้ข้าพเจ้าด้วย!)",
  str_homestory_N26dianying_90060301_55_dialog_content = "(สองรางวัลสำหรับหนึ่งภารกิจ... มันดีเกินกว่าจะผ่านไป!)",
  str_homestory_N26dianying_90060301_56_dialog_content = "ว้าย... ในที่สุดฉันก็มาถึงหมู่บ้านมังกรแล้ว นี่พาฉันกลับไปจริงๆ ...",
  str_homestory_N26dianying_90060301_57_dialog_content = "ก้าวขึ้นไปและดูสิ! อาวุธมหัศจรรย์จากทั่วทุกมุมโลก! ดาบและใบมีดศักดิ์สิทธิ์มากมาย ทั้งหมดนี้ลดราคาแบบดร็อปเดด!",
  str_homestory_N26dianying_90060301_58_dialog_content = "มาหนึ่งมาทั้งหมด! ฉันมีดาบศักดิ์สิทธิ์ทุกประเภทขายที่นี่ แต่ Holy Water Shells ของฉันคือดาวเด่นของรายการ!",
  str_homestory_N26dianying_90060301_59_dialog_content = "อะไร ขอโทษนะ คุณบอกว่าคุณมีดาบศักดิ์สิทธิ์ขายเหรอ?",
  str_homestory_N26dianying_90060301_60_dialog_content = "หากนั่นคือสิ่งที่คุณกำลังมองหา คุณมาถูกที่แล้ว! เฮ้ ฉันยังมี Heavenly Blade อยู่ในสต็อกด้วย ถ้านายสนใจล่ะ?",
  str_homestory_N26dianying_90060301_61_dialog_content = "เห็นดาบนั่นบนชั้นวางอาวุธตรงนั้นไหม? ฉันยอมแลกด้วยราคาต่ำ 99,999,999 ไนเทียม!",
  str_homestory_N26dianying_90060301_62_dialog_content = "หากนั่นคือสิ่งที่คุณกำลังมองหา คุณมาถูกที่แล้ว! เฮ้ ฉันยังมี Heavenly Blade อยู่ในสต็อกด้วย ถ้านายสนใจล่ะ?",
  str_homestory_N26dianying_90060301_63_dialog_content = "เห็นดาบนั่นบนชั้นวางอาวุธตรงนั้นไหม? ฉันยอมแลกด้วยราคาต่ำ 99,999,999 ไนเทียม!",
  str_homestory_N26dianying_90060301_64_dialog_content = "ที่แพงมาก! อาจจะเป็น Heavenly Blade จากตำนานจริงๆ ก็ได้...?",
  str_homestory_N26dianying_90060301_65_dialog_content = "ฮิฮิฮิฮิ... ไม่เลวใช่มั้ย? คุณมีตาที่มีคุณภาพ พลาด!",
  str_homestory_N26dianying_90060301_66_dialog_content = "น่าประทับใจใช่มั้ย คุณมีตาที่มีคุณภาพ พลาด!",
  str_homestory_N26dianying_90060301_67_dialog_content = "นี่ไม่ใช่ดาบสวรรค์",
  str_homestory_N26dianying_90060301_68_dialog_content = "ฮะ? H-คุณรู้ได้อย่างไร?!",
  str_homestory_N26dianying_90060301_69_dialog_content = "ฮะ? H-คุณรู้ได้อย่างไร?!",
  str_homestory_N26dianying_90060301_70_dialog_content = "บอกไม่ถูกว่ารู้ได้ยังไง...เรียกว่าสัญชาตญาณเหรอ?",
  str_homestory_N26dianying_90060301_71_dialog_content = "อะแฮ่ม... ถูกต้องแล้ว! ดาบเล่มนั้นไม่ใช่ Heavenly Blade แต่อย่างใด เพราะดาบเล่มจริง...",
  str_homestory_N26dianying_90060301_72_dialog_content = "ดาบที่อยู่ข้างๆ น่ะเหรอ!",
  str_homestory_N26dianying_90060301_73_dialog_content = "อะแฮ่ม... ถูกต้องแล้ว! ดาบเล่มนั้นไม่ใช่ Heavenly Blade แต่อย่างใด เพราะดาบเล่มจริง...",
  str_homestory_N26dianying_90060301_74_dialog_content = "ดาบที่อยู่ข้างๆ น่ะเหรอ!",
  str_homestory_N26dianying_90060301_75_dialog_content = "จริงหรือ ให้ฉันดู! ...เอ่อ ขอโทษนะ แต่อันนี้ก็ไม่ใช่เรื่องจริงเหมือนกัน!",
  str_homestory_N26dianying_90060301_76_dialog_content = "(ให้ตายเถอะ...ไม่มีทางหลอกเธอหรอก!)",
  str_homestory_N26dianying_90060301_77_dialog_content = "(ให้ตายเถอะ...ไม่มีทางหลอกเธอหรอก!)",
  str_homestory_N26dianying_90060301_78_dialog_content = "ฉันแน่ใจว่าคุณรู้อยู่แล้ว แต่ที่นี่ในหมู่บ้านแห่งมังกร เราไม่ได้พยายามโกงชาวบ้านของเรา ตอนนี้ช่วยบอกฉันทีว่าฉันจะหา Heavenly Blade ที่แท้จริงได้ที่ไหน?",
  str_homestory_N26dianying_90060301_79_dialog_content = "ได้เลย คุณชนะ... เอาล่ะ",
  str_homestory_N26dianying_90060301_80_dialog_content = "ได้เลย คุณชนะ... เอาล่ะ",
  str_homestory_N26dianying_90060301_81_dialog_content = "วีดีโอเทป?!",
  str_homestory_N26dianying_90060301_82_dialog_content = "ไปวางเทปนี้ในโปรเจ็กเตอร์ตรงนั้น แล้วกด \"เล่น\"",
  str_homestory_N26dianying_90060301_83_dialog_content = "โปรเจคเตอร์จะแสดงคำตอบที่คุณต้องการ!",
  str_homestory_N26dianying_90060301_84_dialog_content = "ไปวางเทปนี้ในโปรเจ็กเตอร์ตรงนั้น แล้วกด \"เล่น\"",
  str_homestory_N26dianying_90060301_85_dialog_content = "โปรเจคเตอร์จะแสดงคำตอบที่คุณต้องการ!",
  str_homestory_N26dianying_90060301_86_dialog_content = "อืม... มันควรจะเริ่มเล่นเมื่อฉันกดปุ่มนี้ใช่ไหม?",
  str_homestory_N26dianying_90060301_87_dialog_content = "...ห๊ะ? ทำไมภาพในเทปจึงไม่เคลื่อนไหว ไม่มีเสียงเช่นกัน...",
  str_homestory_N26dianying_90060301_88_dialog_content = "เดี๋ยวนะ เริ่มขยับแล้ว!!",
  str_homestory_N26dianying_90060301_89_dialog_content = "ได้เลย คุณชนะ... เอาล่ะ",
  str_homestory_N26dianying_90060301_90_dialog_content = "ได้เลย คุณชนะ... เอาล่ะ",
  str_homestory_N26dianying_90060301_91_dialog_content = "... แผนที่?!",
  str_homestory_N26dianying_90060301_92_dialog_content = "ใช้แผนที่นี้และเดินตามไปยังตำแหน่งที่ทำเครื่องหมายไว้",
  str_homestory_N26dianying_90060301_93_dialog_content = "แผนที่จะแสดงคำตอบที่คุณต้องการ!",
  str_homestory_N26dianying_90060301_94_dialog_content = "ใช้แผนที่นี้และเดินตามไปยังตำแหน่งที่ทำเครื่องหมายไว้",
  str_homestory_N26dianying_90060301_95_dialog_content = "แผนที่จะแสดงคำตอบที่คุณต้องการ!",
  str_homestory_N26dianying_90060301_96_dialog_content = "อืม... ฉันค่อนข้างแน่ใจว่าฉันมาถูกทางแล้วใช่ไหม?",
  str_homestory_N26dianying_90060301_97_dialog_content = "ถึงกระนั้น ฉันแทบจะจับผิดแผนที่นี้ไม่ได้เลย...",
  str_homestory_N26dianying_90060301_98_dialog_content = "อืม... ฉันต้องดูให้ละเอียดกว่านี้!",
  str_homestory_N26dianying_90060301_99_dialog_content = "ได้เลย คุณชนะ... ดูนั่นสิ",
  str_homestory_N26dianying_90060301_100_dialog_content = "ได้เลย คุณชนะ... ดูนั่นสิ",
  str_homestory_N26dianying_90060301_101_dialog_content = "กล่องจดหมาย?!",
  str_homestory_N26dianying_90060301_102_dialog_content = "ไปอ่านที่เจ้าของเดิมเขียนไว้",
  str_homestory_N26dianying_90060301_103_dialog_content = "กล่องจดหมายจะแสดงคำตอบที่คุณต้องการ!",
  str_homestory_N26dianying_90060301_104_dialog_content = "ไปอ่านที่เจ้าของเดิมเขียนไว้",
  str_homestory_N26dianying_90060301_105_dialog_content = "กล่องจดหมายจะแสดงคำตอบที่คุณต้องการ!",
  str_homestory_N26dianying_90060301_106_dialog_content = "อืม... กล่องจดหมายนี่สูงชะมัดเลยเหรอ?",
  str_homestory_N26dianying_90060301_107_dialog_content = "แต่จากข้างล่างนี่บอกได้เลยว่าเขียนเลอะเทอะเกินกว่าจะอ่านได้...",
  str_homestory_N26dianying_90060301_108_dialog_content = "อืม... ฉันต้องดูให้ละเอียดกว่านี้!",
  str_homestory_N26dianying_90060301_108X1_dialog_content = "ได้เลย คุณชนะ... เอาล่ะ มุ่งหน้าไปทางที่ฉันกำลังเผชิญอยู่",
  str_homestory_N26dianying_90060301_108X2_dialog_content = "ได้เลย คุณชนะ... เอาล่ะ มุ่งหน้าไปทางที่ฉันกำลังเผชิญอยู่",
  str_homestory_N26dianying_90060301_108X3_dialog_content = "ฉันจะไปที่ไหน",
  str_homestory_N26dianying_90060301_108X4_dialog_content = "อืม ไม่ต้องกังวลเรื่องนั้น เดินไปข้างหน้าเท่านั้น!",
  str_homestory_N26dianying_90060301_108X5_dialog_content = "มีความหวังใหม่รอคุณอยู่เสมอที่ Village of Dragons ดินแดนแห่งผู้คนที่โดดเด่น!",
  str_homestory_N26dianying_90060301_108X6_dialog_content = "อืม ไม่ต้องกังวลเรื่องนั้น เดินไปข้างหน้าเท่านั้น!",
  str_homestory_N26dianying_90060301_108X7_dialog_content = "มีความหวังใหม่รอคุณอยู่เสมอที่ Village of Dragons ดินแดนแห่งผู้คนที่โดดเด่น!",
  str_homestory_N26dianying_90060301_108X8_dialog_content = "ร-จริงเหรอ!? ไม่ลำลองเกินไปเหรอ...",
  str_homestory_N26dianying_90060301_108X9_dialog_content = "Geez ฉันพูดถูก เดินมานานมากแล้ว...เจ้านายต้องเป็นคนขี้โกงแน่ๆ!",
  str_homestory_N26dianying_90060301_108X10_dialog_content = "ฮะ? นี่อาจจะเป็น...",
  str_homestory_N26dianying_90060301_109_dialog_content = "\"วิถีของโลกคือการแสวงหาผลประโยชน์ส่วนตัว และด้วยเหตุนี้ โลกจะไม่มีวันเปลี่ยนแปลง เพื่อป้องกันไม่ให้ Heavenly Blade ตกไปอยู่ในมือของคนชั่วร้าย...\"",
  str_homestory_N26dianying_90060301_110_dialog_content = "\"บ่อน้ำโบราณในหมู่บ้านมังกรได้รับพรด้วยพลังที่สามารถเปิดเผยดาบในตำนานได้\"",
  str_homestory_N26dianying_90060301_111_dialog_content = "\"เต็มไปด้วยแสงลึกลับ บ่อน้ำนี้จะไม่แสดงภาพสะท้อนของวัตถุใด ๆ ที่อยู่ในน้ำ\"",
  str_homestory_N26dianying_90060301_112_dialog_content = "\"เมื่อดาบแห่งสวรรค์ที่แท้จริงเข้ามาใกล้ ภาพลักษณ์อันศักดิ์สิทธิ์ของมันจะปรากฏภายในบ่อน้ำ...\"",
  str_homestory_N26dianying_90060301_113_dialog_content = "\"วิถีของโลกคือการแสวงหาผลประโยชน์ส่วนตัว และด้วยเหตุนี้ โลกจะไม่มีวันเปลี่ยนแปลง เพื่อป้องกันไม่ให้ Heavenly Blade ตกไปอยู่ในมือของคนชั่วร้าย...\"",
  str_homestory_N26dianying_90060301_114_dialog_content = "\"เก้าอี้พักผ่อนในหมู่บ้านมังกรได้รับพรด้วยพลังที่สามารถเปิดเผยดาบในตำนานได้\"",
  str_homestory_N26dianying_90060301_115_dialog_content = "\"เต็มไปด้วย Luminatics ลึกลับ เก้าอี้ตัวนี้จะไม่อนุญาตให้ใครนั่งบนที่นั่ง\"",
  str_homestory_N26dianying_90060301_116_dialog_content = "\"เมื่อดาบแห่งสวรรค์ที่แท้จริงเข้ามาใกล้ ภาพลักษณ์อันศักดิ์สิทธิ์ของมันจะปรากฏบนที่นั่ง...\"",
  str_homestory_N26dianying_90060301_117_dialog_content = "\"วิถีของโลกคือการแสวงหาผลประโยชน์ส่วนตัว และด้วยเหตุนี้ โลกจะไม่มีวันเปลี่ยนแปลง เพื่อป้องกันไม่ให้ Heavenly Blade ตกไปอยู่ในมือของคนชั่วร้าย...\"",
  str_homestory_N26dianying_90060301_118_dialog_content = "\"เปียโนในหมู่บ้านมังกรได้รับพรด้วยพลังที่สามารถเปิดเผยดาบในตำนานได้\"",
  str_homestory_N26dianying_90060301_119_dialog_content = "\"เปี่ยมไปด้วยแสงลึกลับ เปียโนนี้จะไม่ยอมให้ใครเล่นมัน\"",
  str_homestory_N26dianying_90060301_120_dialog_content = "\"เมื่อ Heavenly Blade ที่แท้จริงเข้ามาใกล้ ภาพลักษณ์อันศักดิ์สิทธิ์ของมันจะปรากฏบนคีย์ของเปียโน...\"",
  str_homestory_N26dianying_90060301_121_dialog_content = "...เหยา? นั่นคุณเหยาเหรอ?",
  str_homestory_N26dianying_90060301_122_dialog_content = "เหยา? เป็นคุณจริงๆเหรอ?",
  str_homestory_N26dianying_90060301_123_dialog_content = "ฉันเอง ผู้หญิงข้างบ้านตั้งแต่เรายังเด็ก! ฉันไม่ได้เจอคุณนานแล้ว เหยา!",
  str_homestory_N26dianying_90060301_124_dialog_content = "นับตั้งแต่วันที่เจ้าออกจากหมู่บ้านเพื่อหางานทำ... ข้าคิดว่าจะไม่ได้พบเจ้าอีกแล้ว!",
  str_homestory_N26dianying_90060301_125_dialog_content = "อย่างไรก็ตาม คุณกำลังมองหาบางสิ่งอยู่หรือเปล่า?",
  str_homestory_N26dianying_90060301_126_dialog_content = "หลังจากที่เราทั้งสองออกจากหมู่บ้านเพื่อหางานทำ... ฉันคิดว่าจะไม่ได้เจอคุณอีกแล้ว!",
  str_homestory_N26dianying_90060301_127_dialog_content = "อย่างไรก็ตาม คุณกำลังมองหาบางสิ่งอยู่หรือเปล่า?",
  str_homestory_N26dianying_90060301_128_dialog_content = "เรื่องมันยาว แต่... ยังจำกันได้ไหมว่าไปหาที่ไหนกันดี? คุณรู้จักคนนั้นใช่มั้ย?",
  str_homestory_N26dianying_90060301_129_dialog_content = "เรื่องมันยาว แต่... คุณยังจำได้ไหมว่าจะหาเก้าอี้พักผ่อนได้ที่ไหน? คุณรู้จักคนนั้นใช่มั้ย?",
  str_homestory_N26dianying_90060301_130_dialog_content = "เรื่องมันยาว แต่... คุณยังจำได้ไหมว่าจะหาเปียโนได้ที่ไหน? คุณรู้จักคนนั้นใช่มั้ย?",
  str_homestory_N26dianying_90060301_131_dialog_content = "แน่นอน แค่ตามฉันมา แล้วฉันจะแสดงให้คุณเห็น",
  str_homestory_N26dianying_90060301_132_dialog_content = "เราอยู่ที่นี่!",
  str_homestory_N26dianying_90060301_133_dialog_content = "แน่นอน แค่ตามฉันมา แล้วฉันจะแสดงให้คุณเห็น",
  str_homestory_N26dianying_90060301_134_dialog_content = "เอาล่ะ เราอยู่ที่นี่!",
  str_homestory_N26dianying_90060301_135_dialog_content = "นี่... คุณกลับบ้านมาเพื่อดูบ่อน้ำนี้จริงๆ เหรอ?",
  str_homestory_N26dianying_90060301_136_dialog_content = "ดังนั้น... คุณกลับมาบ้านเพียงเพื่อดูเก้าอี้นี้จริงๆ หรือ?",
  str_homestory_N26dianying_90060301_137_dialog_content = "ดังนั้น... คุณกลับบ้านเพียงเพื่อดูเปียโนนี้จริงๆ หรือ?",
  str_homestory_N26dianying_90060301_138_dialog_content = "ความจริงก็คือ... ฉันมาเพื่อค้นหาเบาะแสเกี่ยวกับที่อยู่ของ Heavenly Blade",
  str_homestory_N26dianying_90060301_139_dialog_content = "เจ้านายของฉันสั่งให้ฉันหามันและนำมันกลับมาให้พวกเขาโดยเร็วที่สุด",
  str_homestory_N26dianying_90060301_140_dialog_content = "<color=#FFB400>\"ลอร์ด\"</color>? ใน \"มากกว่าหนึ่ง\"?",
  str_homestory_N26dianying_90060301_141_dialog_content = "<color=#FFB400>\"ลอร์ด\"</color>? เช่นเดียวกับใน \"มากกว่าหนึ่ง\"? ...โอ้ คุณหมายถึงหัวหน้าของคุณ!",
  str_homestory_N26dianying_90060301_142_dialog_content = "ใช่แล้ว... ทั้งสองคนมอบหมายภารกิจเดียวกันให้ฉันทำในเวลาเดียวกัน ดังนั้นฉันจึงมาอยู่ที่นี่",
  str_homestory_N26dianying_90060301_143_dialog_content = "แม้ว่าฉันไม่แน่ใจว่าฉันจะทำอย่างไรเมื่อพบมัน... ฉันควรตัดสินใจอย่างไรว่าจะมอบให้ใคร?",
  str_homestory_N26dianying_90060301_144_dialog_content = "ทำไมไม่มี \"ลอร์ด\" ของคุณ <color=#FFB400>ต่อสู้กัน</color> สำหรับมัน?",
  str_homestory_N26dianying_90060301_145_dialog_content = "อย่างไรก็ตาม น้ำในบ่อนี้ขุ่นมาก ไม่เห็นมี \"รูปเทพ\" ตรงไหนเลย...",
  str_homestory_N26dianying_90060301_146_dialog_content = "อย่างไรก็ตามเก้าอี้ตัวนี้ว่างเปล่า ไม่เห็นมี \"รูปเทพ\" ตรงไหนเลย...",
  str_homestory_N26dianying_90060301_147_dialog_content = "อย่างไรก็ตาม คีย์บนเปียโนเครื่องนี้ก็สะอาดสะอ้าน ไม่เห็นมี \"รูปเทพ\" บนตัวเลย...",
  str_homestory_N26dianying_90060301_147X1_dialog_content = "...เหยา? นั่นคุณเหยาเหรอ?",
  str_homestory_N26dianying_90060301_147X2_dialog_content = "เหยา? เป็นคุณจริงๆเหรอ?",
  str_homestory_N26dianying_90060301_147X3_dialog_content = "ฉันเอง ผู้หญิงข้างบ้านตั้งแต่เรายังเด็ก! ฉันไม่ได้เจอคุณนานแล้ว เหยา!",
  str_homestory_N26dianying_90060301_147X4_dialog_content = "นับตั้งแต่วันที่เจ้าออกจากหมู่บ้านเพื่อหางานทำ... ข้าคิดว่าจะไม่ได้พบเจ้าอีกแล้ว!",
  str_homestory_N26dianying_90060301_147X5_dialog_content = "อย่างไรก็ตาม คุณกำลังมองหาบางสิ่งอยู่หรือเปล่า?",
  str_homestory_N26dianying_90060301_147X6_dialog_content = "หลังจากที่เราทั้งสองออกจากหมู่บ้านเพื่อหางานทำ... ฉันคิดว่าจะไม่ได้เจอคุณอีกแล้ว!",
  str_homestory_N26dianying_90060301_147X7_dialog_content = "ว่าไงนะ คุณกำลังทำอะไรอยู่?",
  str_homestory_N26dianying_90060301_147X8_dialog_content = "อืม อย่าพูดถึงมัน ลอร์ดสองคนของฉันขอให้ฉันค้นหา Heavenly Blade อันเดียวกัน",
  str_homestory_N26dianying_90060301_147X9_dialog_content = "สุดท้ายก็ไม่เจออะไรเลย...",
  str_homestory_N26dianying_90060301_147X10_dialog_content = "คุณได้รับใช้นายสองคนมาตลอด! และหลังจากที่ฉันเชื่อใจคุณมากขนาดนี้!",
  str_homestory_N26dianying_90060301_147X11_dialog_content = "ล-ลอร์ด ซากุระ?! ว-คุณมาทำอะไรที่นี่...?",
  str_homestory_N26dianying_90060301_147X12_dialog_content = "ฉันควรจะถามคำถามเดียวกันกับคุณ! คำพูดไม่สามารถอธิบายได้ว่าฉันรู้สึกผิดหวังในตัวคุณมากเพียงใด สิ่งที่ฉันเรียกว่า \"ผู้รับใช้ที่ซื่อสัตย์\"!",
  str_homestory_N26dianying_90060301_147X13_dialog_content = "แอล-ลอร์ด ดราก้อนสกอร์ช?! คุณอยู่ที่นี่ด้วยเหรอ!",
  str_homestory_N26dianying_90060301_147X14_dialog_content = "เอ่อ... อะ-เกิดอะไรขึ้นที่นี่?",
  str_homestory_N26dianying_90060301_147X15_dialog_content = "เอ่อ... อะ-เกิดอะไรขึ้นที่นี่?",
  str_homestory_N26dianying_90060301_147X16_dialog_content = "อื้อหือ... เหมือนจิ๊กโก๋ขึ้น! ชับบ์!",
  str_homestory_N26dianying_90060301_147X17_dialog_content = "ฉันกังวลว่างานนี้ยิ่งใหญ่เกินไปสำหรับคุณคนเดียว ดังนั้นฉันจึงจัดคนติดตามคุณในระหว่างภารกิจของคุณ...",
  str_homestory_N26dianying_90060301_147X18_dialog_content = "และรายงานทุกอย่างที่เกิดขึ้นให้ฉันทราบ มันควรจะเป็นการทดสอบความสามารถของคุณ",
  str_homestory_N26dianying_90060301_147X19_dialog_content = "เมื่อข้ารู้ว่าการค้นหาของเจ้าเริ่มประสบผล ข้าจึงรีบไปช่วยเจ้าหา Heavenly Blade...",
  str_homestory_N26dianying_90060301_147X20_dialog_content = "เพียงเพื่อจะได้ยินคุณพูดคำที่น่ากลัวและน่ากลัวเหล่านั้น!",
  str_homestory_N26dianying_90060301_147X21_dialog_content = "ดี? คุณต้องพูดอะไรเพื่อป้องกันคนทรยศ!",
  str_homestory_N26dianying_90060301_147X22_dialog_content = "ก็...ในเมื่อเกิดเรื่องแบบนี้ขึ้น ฉันจะรับผิดชอบเอง!",
  str_homestory_N26dianying_90060301_147X23_dialog_content = "ดำเนินการเจ้านายของฉัน! ฉันรู้กฎ วันนี้เป็นวันที่ฉันตาย!",
  str_homestory_N26dianying_90060301_147X24_dialog_content = "หา?",
  str_homestory_N26dianying_90060301_147X25_dialog_content = "ฆ่าคุณ? นี่เป็นเรื่องตลกแบบไหน?",
  str_homestory_N26dianying_90060301_147X26_dialog_content = "ในฐานะนักรบผู้เย่อหยิ่ง ข้าจะไม่ฆ่าศัตรูที่ไม่มีอาวุธ",
  str_homestory_N26dianying_90060301_147X27_dialog_content = "แม้ว่าเจ้าจะทรยศ แต่ความสำนึกผิดของเจ้าก็ดูจริงใจ... ดีมาก คนรับใช้ของข้า กลับบ้านเราเถอะจะได้ลงโทษตามนั้น",
  str_homestory_N26dianying_90060301_147X28_dialog_content = "อะไร ฉันเป็นคนแรกที่มาถึง ดังนั้นการลงโทษของ Dragonscorch ควรมาก่อน!",
  str_homestory_N26dianying_90060301_147X29_dialog_content = "ฉันว่าซากุระ!",
  str_homestory_N26dianying_90060301_147X30_dialog_content = "ฉันพูดว่า Dragonscorch!",
  str_homestory_N26dianying_90060301_147X31_dialog_content = "ฮู-อา!",
  str_homestory_N26dianying_90060301_147X32_dialog_content = "ได้โปรด ท่านลอร์ด... นี่ไม่ใช่สิ่งที่ท่านควรจะต่อสู้เพื่อ...",
  str_homestory_N26dianying_90060301_148_dialog_content = "คุณได้รับใช้นายสองคนมาตลอด! และหลังจากที่ฉันเชื่อใจคุณมากขนาดนี้!",
  str_homestory_N26dianying_90060301_149_dialog_content = "ล-ลอร์ด ซากุระ?! ว-คุณมาทำอะไรที่นี่...?",
  str_homestory_N26dianying_90060301_150_dialog_content = "ฉันควรจะถามคำถามเดียวกันกับคุณ! คำพูดไม่สามารถอธิบายได้ว่าฉันรู้สึกผิดหวังในตัวคุณมากเพียงใด สิ่งที่ฉันเรียกว่า \"ผู้รับใช้ที่ซื่อสัตย์\"!",
  str_homestory_N26dianying_90060301_151_dialog_content = "แอล-ลอร์ด ดราก้อนสกอร์ช?! คุณอยู่ที่นี่ด้วยเหรอ!",
  str_homestory_N26dianying_90060301_152_dialog_content = "เอ่อ... อะ-เกิดอะไรขึ้นที่นี่?",
  str_homestory_N26dianying_90060301_153_dialog_content = "เอ่อ... อะ-เกิดอะไรขึ้นที่นี่?",
  str_homestory_N26dianying_90060301_154_dialog_content = "อื้อหือ... เหมือนจิ๊กโก๋ขึ้น! ชับบ์!",
  str_homestory_N26dianying_90060301_155_dialog_content = "ฉันกังวลว่างานนี้ยิ่งใหญ่เกินไปสำหรับคุณคนเดียว ดังนั้นฉันจึงจัดคนติดตามคุณในระหว่างภารกิจของคุณ...",
  str_homestory_N26dianying_90060301_156_dialog_content = "และรายงานทุกอย่างที่เกิดขึ้นให้ฉันทราบ มันควรจะเป็นการทดสอบความสามารถของคุณ",
  str_homestory_N26dianying_90060301_157_dialog_content = "เมื่อข้ารู้ว่าการค้นหาของเจ้าเริ่มประสบผล ข้าจึงรีบไปช่วยเจ้าหา Heavenly Blade...",
  str_homestory_N26dianying_90060301_158_dialog_content = "เพียงเพื่อจะได้ยินคุณพูดคำที่น่ากลัวและน่ากลัวเหล่านั้น!",
  str_homestory_N26dianying_90060301_159_dialog_content = "ดี? คุณต้องพูดอะไรเพื่อป้องกันคนทรยศ!",
  str_homestory_N26dianying_90060301_160_dialog_content = "เอ๋?!",
  str_homestory_N26dianying_90060301_161_dialog_content = "กล้าเยาะเย้ยฉันเหรอ!",
  str_homestory_N26dianying_90060301_162_dialog_content = "(พวกเขาคิดเหมือนกันทุกประการ ไม่พวกเขา...)",
  str_homestory_N26dianying_90060301_163_dialog_content = "พวกเขาพร้อมเพรียงกัน! ชับบ์!",
  str_homestory_N26dianying_90060301_164_dialog_content = "Lord Dragonscorch... นี่คงเป็นโชคชะตา จะมีเวลาใดดีไปกว่าการตัดสินใจว่าใครคือผู้ที่แข็งแกร่งที่สุด... มากกว่าตอนนี้!",
  str_homestory_N26dianying_90060301_165_dialog_content = "คุณเอาคำพูดออกจากปากฉันทันที วันนี้เป็นวันที่ Dragonscorch พิสูจน์ความยิ่งใหญ่ของมัน!",
  str_homestory_N26dianying_90060301_166_dialog_content = "ฮู-อา!",
  str_homestory_N26dianying_90060301_167_dialog_content = "(โอ้ย... พวกมันกำลังจะฉีกหน้ากัน! ฉันต้องทำอะไรสักอย่างแล้วสินะ...)",
  str_homestory_N26dianying_90060301_168_option_content = "ตามหาดาบแห่งสวรรค์!",
  str_homestory_N26dianying_90060301_169_dialog_content = "เฮ้! อย่าลืมเป้าหมายของภารกิจของคุณ!",
  str_homestory_N26dianying_90060301_170_dialog_content = "ถูกตัอง! สิ่งที่สำคัญที่สุดในตอนนี้... คือการตามหา Heavenly Blade!",
  str_homestory_N26dianying_90060301_171_dialog_content = "บางทีถ้าฉันเพ่งดูใกล้ๆ อาจมี \"รูปเทพ\" ปรากฏขึ้น...",
  str_homestory_N26dianying_90060301_172_dialog_content = "ห-หา?!",
  str_homestory_N26dianying_90060301_173_dialog_content = "เจ้านายของฉัน! มาดูกันเร็ว!",
  str_homestory_N26dianying_90060301_174_dialog_content = "หืมม?",
  str_homestory_N26dianying_90060301_175_dialog_content = "อาจจะเป็น... ดาบสวรรค์?!",
  str_homestory_N26dianying_90060301_176_dialog_content = "นั่นอะไรน่ะ...?",
  str_homestory_N26dianying_90060301_177_dialog_content = "ทำไมใบมีดของฉันถึงส่องแสงเช่นนี้?",
  str_homestory_N26dianying_90060301_178_dialog_content = "ถึงเวลาแล้ว! ในที่สุด Heavenly Blade ก็ได้รวมเป็นหนึ่งอีกครั้ง!",
  str_homestory_N26dianying_90060301_179_dialog_content = "ถึงเวลาแล้ว! ในที่สุด Heavenly Blade ก็ได้รวมเป็นหนึ่งอีกครั้ง!",
  str_homestory_N26dianying_90060301_180_dialog_content = "เอ๊ะ...",
  str_homestory_N26dianying_90060301_181_dialog_content = "ถูกตัอง! ที่เรียกว่า \"ดาบสวรรค์\"... แท้จริงแล้วคือดาบคู่! และเมื่อพวกมันมารวมกัน พลังที่แท้จริงของพวกมันจะเผยออกมาในที่สุด",
  str_homestory_N26dianying_90060301_182_dialog_content = "นานมาแล้ว ฉันมีโอกาสดูนักรบผู้ยิ่งใหญ่สองคนตัดผ่าน Eclipsites ด้วยใบมีดทั้งสองนี้...",
  str_homestory_N26dianying_90060301_183_dialog_content = "ถูกตัอง! จริงๆ แล้วมี Heavenly Blades สองอัน และพลังที่แท้จริงของพวกมันจะเผยออกมาก็ต่อเมื่อพวกมันมารวมกัน!",
  str_homestory_N26dianying_90060301_184_dialog_content = "เมื่อฉันยังเด็ก ฉันเห็นนักรบในตำนานสองคนตัดผ่านกองทัพของ Eclipsites ด้วยดาบทั้งสองนี้...",
  str_homestory_N26dianying_90060301_185_dialog_content = "นั่นเป็นครั้งสุดท้ายที่ดาบทั้งสองถูกใช้ร่วมกัน หลังจากการสู้รบครั้งนั้น พวกเขาตกอยู่ในเงื้อมมือที่แยกจากกันและถูกกันให้ห่างจากกันตั้งแต่นั้นเป็นต้นมา",
  str_homestory_N26dianying_90060301_186_dialog_content = "นั่นเป็นครั้งสุดท้ายที่ดาบทั้งสองถูกใช้ร่วมกัน หลังจากการสู้รบครั้งนั้น พวกเขาตกอยู่ในเงื้อมมือที่แยกจากกันและถูกกันให้ห่างจากกันตั้งแต่นั้นเป็นต้นมา",
  str_homestory_N26dianying_90060301_187_dialog_content = "แต่ตอนนี้ Heavenly Blade กลับมาสมบูรณ์อีกครั้ง!",
  str_homestory_N26dianying_90060301_188_dialog_content = "แต่ตอนนี้ Heavenly Blade กลับมาสมบูรณ์อีกครั้ง!",
  str_homestory_N26dianying_90060301_189_dialog_content = "ธ-ถูกต้องแล้ว ท่านลอร์ด! แม้จะมีความแตกต่าง แต่เป้าหมายของคุณก็เป็นหนึ่งเดียวกัน... คุณยังคิดเหมือนกันมาก!",
  str_homestory_N26dianying_90060301_190_dialog_content = "แทนที่จะต่อสู้กันเอง ทำไมไม่รวมกองกำลังของคุณแล้วกอบกู้โลกด้วยกันล่ะ?",
  str_homestory_N26dianying_90060301_191_dialog_content = "อืมม...",
  str_homestory_N26dianying_90060301_192_dialog_content = "เอ่อ...",
  str_homestory_N26dianying_90060301_193_dialog_content = "คนรับใช้ให้เหตุผลที่ถูกต้อง... ท้ายที่สุด เราต่างก็แสวงหาพลังของ Heavenly Blade",
  str_homestory_N26dianying_90060301_194_dialog_content = "และถ้าเรารวมพลังกัน เราจะยังคงเป็นผู้นำของกลุ่มที่มีอำนาจมากที่สุดในโลก",
  str_homestory_N26dianying_90060301_195_dialog_content = "ส่วนคุณบ่าว \"ผู้ซื่อสัตย์\" ของเรา...",
  str_homestory_N26dianying_90060301_196_dialog_content = "ต้องเป็นเรื่องไม่ดีแน่ ๆ...",
  str_homestory_N26dianying_90060301_197_dialog_content = "คุณได้พิสูจน์คุณค่าของคุณแล้ว และซากุระจะเป็นหนี้คุณตลอดไป!",
  str_homestory_N26dianying_90060301_198_dialog_content = "Dragonscorch ก็เป็นหนี้ความพยายามของคุณเช่นกัน!",
  str_homestory_N26dianying_90060301_199_dialog_content = "<size=45>เจ้านายของฉัน!</size>",
  str_homestory_N26dianying_90060301_200_dialog_content = "ฮิฮิฮิฮิ... และแล้ว ตำนานบทใหม่ก็ถือกำเนิดขึ้น!",
  str_homestory_N26dianying_90060301_201_dialog_content = "ฮิฮิ! และแล้ว ตำนานบทใหม่ก็ถือกำเนิดขึ้น!",
  str_homestory_N26dianying_90060301_202_dialog_content = "\"ในท้ายที่สุด Zakura และ Dragonscorch ได้ละทิ้งความแตกต่างและรวมเป็นกองทัพที่ทรงพลัง\"",
  str_homestory_N26dianying_90060301_203_dialog_content = "\"ด้วยพลังที่รวมกันของพวกเขา เช่นเดียวกับพลังของ Heavenly Blade โลกก็มีความสุขด้วยความสงบสุขอีกครั้ง\"",
  str_homestory_N26dianying_90060301_204_dialog_content = "\"ในท้ายที่สุด Zakura และ Dragonscorch ได้ละทิ้งความแตกต่างและรวมเป็นกองทัพที่ทรงพลัง\"",
  str_homestory_N26dianying_90060301_205_dialog_content = "\"ด้วยพลังที่รวมกันของพวกเขา เช่นเดียวกับพลังของ Heavenly Blade โลกก็มีความสุขด้วยความสงบสุขอีกครั้ง\"",
  str_homestory_N26dianying_90060301_206_option_content = "พยายามแก้ไข!",
  str_homestory_N26dianying_90060301_207_dialog_content = "คุณรู้จักสองคนนี้ดีกว่าใคร! ไปจัดการสิ่งต่าง ๆ ระหว่างพวกเขา!",
  str_homestory_N26dianying_90060301_208_dialog_content = "ถูกตัอง! ในฐานะคนรับใช้ของพวกเขา ฉันเป็นคนเดียวที่สามารถยุติความแตกต่างของพวกเขาได้!",
  str_homestory_N26dianying_90060301_209_dialog_content = "เจ้านายของข้าพเจ้า ถ้าข้าพเจ้าพูดได้? แม้ว่าความแตกต่างของคุณ เป้าหมายของคุณเหมือนกัน... คุณคิดเหมือนกันมาก!",
  str_homestory_N26dianying_90060301_210_dialog_content = "แทนที่จะต่อสู้กันเอง ทำไมไม่รวมกองกำลังของคุณแล้วกอบกู้โลกด้วยกันล่ะ?",
  str_homestory_N26dianying_90060301_211_dialog_content = "อืมม...",
  str_homestory_N26dianying_90060301_212_dialog_content = "เอ่อ...",
  str_homestory_N26dianying_90060301_213_dialog_content = "คนรับใช้ให้ประเด็นที่ถูกต้อง ในฐานะผู้นำของกลุ่มต่าง ๆ ของเรา หน้าที่ของเราคือปกป้องโลกจากภัยจากสุริยุปราคา",
  str_homestory_N26dianying_90060301_214_dialog_content = "และถ้าเรารวมพลังกัน เราจะยังคงเป็นผู้นำของกลุ่มที่มีอำนาจมากที่สุดในโลก",
  str_homestory_N26dianying_90060301_215_dialog_content = "ส่วนคุณบ่าว \"ผู้ซื่อสัตย์\" ของเรา...",
  str_homestory_N26dianying_90060301_216_dialog_content = "ต้องเป็นเรื่องไม่ดีแน่ ๆ...",
  str_homestory_N26dianying_90060301_217_dialog_content = "แม้ว่าคุณจะล้มเหลวในการค้นหา Heavenly Blade... อาจมีทางอื่นที่จะช่วยโลกได้",
  str_homestory_N26dianying_90060301_218_dialog_content = "หาก Dragonscorch และ Zakura เป็นหนึ่งเดียวกัน ก็ไม่จำเป็นต้องลงโทษคุณสำหรับการทรยศของคุณ",
  str_homestory_N26dianying_90060301_219_dialog_content = "<size=45>เจ้านายของฉัน!</size>",
  str_homestory_N26dianying_90060301_220_dialog_content = "ฮิฮิฮิฮิ... และแล้ว ตำนานบทใหม่ก็ถือกำเนิดขึ้น!",
  str_homestory_N26dianying_90060301_221_dialog_content = "ฮิฮิ! และแล้ว ตำนานบทใหม่ก็ถือกำเนิดขึ้น!",
  str_homestory_N26dianying_90060301_222_dialog_content = "\"ในท้ายที่สุด Zakura และ Dragonscorch ได้ละทิ้งความแตกต่างและรวมเป็นกองทัพที่ทรงพลัง\"",
  str_homestory_N26dianying_90060301_223_dialog_content = "\"แล้วโลกก็สุขสงบอีกครั้ง\"",
  str_homestory_N26dianying_90060301_224_dialog_content = "\"ในท้ายที่สุด Zakura และ Dragonscorch ได้ละทิ้งความแตกต่างและรวมเป็นกองทัพที่ทรงพลัง\"",
  str_homestory_N26dianying_90060301_225_dialog_content = "\"แล้วโลกก็สุขสงบอีกครั้ง\"",
  str_homestory_N26dianying_90060301_226_option_content = "แค่ฆ่าฉัน!",
  str_homestory_N26dianying_90060301_227_dialog_content = "ผ-ฉันควรทำอย่างไร? ฉันไม่เห็นวิธีแก้ไขอีกต่อไป...",
  str_homestory_N26dianying_90060301_228_dialog_content = "ไม่ เดี๋ยวก่อน... ฉันผิดเองที่เรื่องมันกลายเป็นแบบนี้ ฉันต้องรับผิดชอบต่อการกระทำของฉัน...",
  str_homestory_N26dianying_90060301_229_dialog_content = "เจ้านายของฉัน! ฉันเป็นคนรับผิดชอบเรื่องทั้งหมดนี้! ถ้าจะฆ่าใครก็ฆ่าฉันสิ!",
  str_homestory_N26dianying_90060301_230_dialog_content = "หา?",
  str_homestory_N26dianying_90060301_231_dialog_content = "ฆ่าคุณ? นี่เป็นเรื่องตลกแบบไหน?",
  str_homestory_N26dianying_90060301_232_dialog_content = "ในฐานะนักรบผู้เย่อหยิ่ง ข้าจะไม่ฆ่าศัตรูที่ไม่มีอาวุธ",
  str_homestory_N26dianying_90060301_233_dialog_content = "แม้ว่าเจ้าจะทรยศ แต่ความสำนึกผิดของเจ้าก็ดูจริงใจ... ดีมาก คนรับใช้ของข้า กลับบ้านเราเถอะจะได้ลงโทษตามนั้น",
  str_homestory_N26dianying_90060301_234_dialog_content = "อะไร ฉันเป็นคนแรกที่มาถึง ดังนั้นการลงโทษของ Dragonscorch ควรมาก่อน!",
  str_homestory_N26dianying_90060301_235_dialog_content = "ฉันว่าซากุระ!",
  str_homestory_N26dianying_90060301_236_dialog_content = "ฉันพูดว่า Dragonscorch!",
  str_homestory_N26dianying_90060301_237_dialog_content = "ฮู-อา!",
  str_homestory_N26dianying_90060301_238_dialog_content = "ได้โปรด ท่านลอร์ด... นี่ไม่ใช่สิ่งที่ท่านควรจะต่อสู้เพื่อ...",
  str_homestory_N26dianying_90060301_239_dialog_content = "ถ้าฉันจำไม่ผิด ร้านนี้ขายอาวุธที่ดีที่สุดในหมู่บ้านมังกรทั้งหมด!",
  str_homestory_N26dianying_90060301_240_dialog_content = "หา?!",
  str_homestory_N26dianying_90060301_241_dialog_content = "เกิดอะไรขึ้นกับอาวุธทั้งหมด? เกลี้ยงร้าน!",
  str_homestory_N26dianying_90060301_242_dialog_content = "อย่าเตือนฉัน ... ขอโทษเพื่อน แต่ฉันปิดตัวลงโดยดี",
  str_homestory_N26dianying_90060301_243_dialog_content = "*สะอื้น* อย่าเตือนฉัน... ขอโทษนะ แต่ร้านทำเพื่อ.",
  str_homestory_N26dianying_90060301_244_dialog_content = "แล้วเกิดอะไรขึ้น",
  str_homestory_N26dianying_90060301_245_dialog_content = "หมู่บ้านถูกปล้นโดยกลุ่มโจรเมื่อวานนี้",
  str_homestory_N26dianying_90060301_246_dialog_content = "หมู่บ้านถูกปล้นโดยกลุ่มโจรเมื่อวานนี้",
  str_homestory_N26dianying_90060301_247_dialog_content = "พวกเขาเอาทุกอย่าง! อาวุธของฉัน เงินของฉัน โฉนดบ้านของฉัน... พวกเขายังเอาชั้นวางอาวุธจักรกลที่ฉันชื่นชอบไปด้วย!",
  str_homestory_N26dianying_90060301_248_dialog_content = "พวกเขาเอาทุกอย่าง! Holy Water Shells ของฉัน เงินของฉัน... พวกมันยังเอาชั้นวางอาวุธจักรกลที่ฉันชื่นชอบไปด้วย!",
  str_homestory_N26dianying_90060301_249_dialog_content = "ฉันไม่เหลืออะไรแล้ว!",
  str_homestory_N26dianying_90060301_250_dialog_content = "ฉันไม่เหลืออะไรแล้ว!",
  str_homestory_N26dianying_90060301_251_dialog_content = "น-ไม่มีอะไรเลยเหรอ?!",
