  str_homestory_N26dianying_90060301_253_dialog_content = "ฮะ? โอ้ ปล่อยฉันไว้คนเดียวเถอะ...",
  str_homestory_N26dianying_90060301_254_dialog_content = "ฮะ? โอ้ ปล่อยฉันไว้คนเดียวเถอะ...",
  str_homestory_N26dianying_90060301_255_dialog_content = "คุณไม่เห็นหรือว่าตอนนี้ฉันกำลังหมกมุ่นอยู่กับความสิ้นหวัง?!",
  str_homestory_N26dianying_90060301_256_dialog_content = "ตอนนี้ฉันบังคับตัวเองให้ยิ้มไม่ได้ พูดเรื่องอาวุธน้อยลงมาก...",
  str_homestory_N26dianying_90060301_257_dialog_content = "แต่กลับ...",
  str_homestory_N26dianying_90060301_258_dialog_content = "เอาล่ะ เพียงพอแล้ว! ร้านปิดแล้วเด้อ!",
  str_homestory_N26dianying_90060301_259_dialog_content = "เอาล่ะ เพียงพอแล้ว! ร้านปิดแล้วเด้อ!",
